INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('f11ea053-6200-40e2-8014-88d7fd040e4c', 'Motux 240ml', 'Razux', 'Motocicletas', '25.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQC9glK_wwZ6iSOVICA7agBGXOWUVn7TvnzJCJFLzQZNQ&s=10', 'O Motux 240ml da Razux é um produto específico para motocicletas, desenvolvido para limpeza, proteção e renovação das superfícies plásticas e pintadas. Sua fórmula compacta e de alta concentração proporciona resultados profissionais em todos os tipos de moto, desde naked a esportivas. Ideal para quem cuida da moto com a mesma atenção dedicada aos carros.', NULL, '2026-07-19 12:17:20.841073+00', '293', '{"length":5.33,"width":5,"height":23}', 'Disponível') ON CONFLICT (id) DO NOTHING;
