INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0a9bf38f-882e-45fb-8588-5cbfd284d5c6', 'Carnauba wash & wax 1892ML', 'Mothers', 'Lava auto', '150', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTQEAWFQ0A5lqwNHlYnQwyAMRnf2wxv7NdVZSoj78Py4Q&s=10', 'O Carnauba Wash & Wax 1892ml da Mothers é um shampoo enriquecido com cera de carnaúba pura para uma lavagem que limpa e protege ao mesmo tempo. Sua fórmula exclusiva remove a sujeira com eficiência enquanto deposita uma fina camada de carnaúba na pintura, intensificando o brilho e a hidrofobia. Aroma fresco e suave. Rende muito por diluição eficiente. O top de linha americano em shampoos com cera.', NULL, '2026-07-19 12:17:20.432966+00', '2100', '{"length":14,"width":14,"height":28}', 'Disponível') ON CONFLICT (id) DO NOTHING;
