INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('783eaac3-cfe5-4fb0-babb-1b83b16a3416', 'Extreme 500ml', 'Auto América', 'Lava auto', '18.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR5n1xD03EaC9BQLS7dIgjL8AdHoQ2d5LJQ32N3cm4x5w&s', 'O Extreme 500ml da Auto América é um shampoo automotivo concentrado de alto rendimento para a lavagem completa do veículo. Sua fórmula com agentes ativos de alta eficácia remove sujeira, barro e resíduos orgânicos com facilidade, sem agredir a cera ou selante existente na pintura. Gera espuma generosa e de fácil enxágue. Ideal para lavagem regular.', NULL, '2026-07-19 12:17:20.841073+00', '560', '{"length":7,"width":7,"height":21,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
