INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('b6d70195-ff80-4e95-8707-1577b2579afa', 'Toalha microfibra Dual Loop 40x40cm 360gsm cinza', 'Kers', 'Toalhas', '9.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQo73WvMUtlBYeDP9VaPslSkU2hd4OYMjr68gqmNCOo7w&s=10', 'A Toalha de Microfibra Dual Loop 40x40cm 360gsm Cinza da Kers é uma toalha multifuncional de alta qualidade para acabamento e remoção de produtos durante o detalhamento. O tecido Dual Loop com fibras entrelaçadas proporciona alta capacidade de absorção e suavidade extrema, sendo segura para todas as superfícies da pintura. Lavável e durável para uso profissional diário.', NULL, '2026-07-21 10:59:42.780268+00', '140', '{"length":42,"width":42,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('295cbc88-fc88-4f84-867e-4612b31c739a', 'adaptador lavor', 'Nação Detail', 'Acessórios', '55', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQxFVgEQr6kyfaInUbs8anfD5xoOOx4QkJGE4dmF1VpHQ&s=10', 'O Adaptador Lavor da Nação Detail é um acessório essencial para quem utiliza lavadoras de alta pressão da marca Lavor em rotinas de limpeza e detalhamento automotivo. Com encaixe preciso e vedação eficiente, garante compatibilidade total com mangueiras e pistolas para a série, proporcionando mais versatilidade e praticidade ao setup de lavagem. Material resistente à pressão e à temperatura, garantindo longa vida útil.', NULL, '2026-07-19 12:17:21.430765+00', '120', '{"length":15,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('16c6aea9-5af2-4187-8297-db30253b40a4', 'Refino step 2 500ml', 'Auto América', 'Polimento', '89.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQdE_1sDFYU39Iy4nTHVlUVgQV4BTXlgu1qk70-q3kOhQ&s=10', 'O Refino Step 2 500ml da Auto América é um composto de polimento de corte médio-baixo para a segunda etapa do processo de correção de pintura. Remove as marcas deixadas pelo composto de corte Step 1, reduzindo a abrasividade e revelando mais brilho e profundidade na pintura. Compatível com politrizes orbitais e rotativas para acabamento impecável.', NULL, '2026-07-19 12:17:20.998748+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('027cd91f-077e-491f-a3b2-8c8fa8ea1541', 'Pulverizador elétrico multi spray Capacidade 2L', 'Kers', 'Equipamentos', '199', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ2eDX7CvbmkhEPp3EcBTGKzTSN87Bl9valBJEAOa_21A&s=10', 'O Pulverizador Elétrico Multi Spray 2L da Kers é um borrifador elétrico de alta tecnologia para aplicação de produtos líquidos de detalhamento de forma rápida, uniforme e sem esforço. Com capacidade de 2 litros e bomba elétrica recarregável, permite aplicar shampoos, dressings e outros produtos de forma eficiente. Elimina a fadiga gerada pelo uso de pulverizadores manuais em grandes volumes.', NULL, '2026-07-22 11:31:11.093007+00', '1200', '{"length":30,"width":20,"height":15}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('617c184e-ccd3-44e2-958a-d620fa510101', 'Descole 500ml', 'Cadillac', 'Específicos', '60.8', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRt9ndwqiV7nNc8T3oQWTMynlxs27D1CofAf3ZAlFnOzw&s=10', 'O Descole 500ml da Cadillac é um removedor especializado para adesivos, etiquetas, piche, resina de árvore e outras substâncias de alta aderência na pintura e vidros do veículo. Sua fórmula de ação rápida dissolve o material sem atacar a pintura ou deixar resíduos gordurosos. Ideal para remover com segurança adesivos velhos, plotagens e películas sem danificar a superfície.', NULL, '2026-07-19 12:17:20.432966+00', '560', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
