INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('5811dae3-ffc0-4ee1-bc2f-6ae91d8af099', 'engate rapido 1/4', 'Detailer', 'Acessórios', '38', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSF8ZmV9gH91tKpbDkE-9fB-Pat5cLiINHSx--J0BIV6g&s=10', 'O Engate Rápido 1/4 da Detailer é um acessório essencial para conexão veloz e segura de mangueiras e pistolas em lavadoras de alta pressão. Fabricado em latão ou aço inoxidável de alta qualidade, suporta pressões elevadas e garante vedação sem vazamentos. O sistema de encaixe rápido permite trocas ágeis de acessórios sem interrupções durante o trabalho.', NULL, '2026-07-19 12:17:21.430765+00', '80', '{"length":10,"width":4,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4bd7bb36-b709-463c-9b6d-279ac5836440', 'Extreme tire gel 500ml', 'Auto América', 'Pneus e rodas', '45.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJHYFf4qGN1HBHr0MiABQSpO18i-uZvrNHa56MpWU1qw&s=10', 'O Extreme Tire Gel 500ml da Auto América é um revitalizador de pneus em gel de alta viscosidade, desenvolvido para proporcionar brilho intenso e duradouro com efeito molhado profissional. Sua fórmula enriquecida com polímeros protetores adere à borracha, repelindo sujeira e água, e protegendo contra os raios UV. Aplicação simples com aplicador de pneu para resultado impecável.', NULL, '2026-07-19 12:17:20.841073+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
