INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('a8b982b7-22d6-4de5-8abe-e1289f174773', 'tubeira azul', 'Nação Detail', 'Acessórios', '150', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSLGHqKmsD9XrZntM7NhTzXNLa-qpJPVa0Dcyf5ivjT3w&s=10', 'A Tubeira Azul da Nação Detail é um bico de lavadora de alta pressão com ângulo de jato específico para trabalhos de detalhamento, proporcionando pressão concentrada para a remoção de sujeiras difíceis em frestas, rodas e áreas específicas. Fabricada em material de alta durabilidade, compatível com os principais sistemas de engate rápido do mercado.', NULL, '2026-07-19 12:17:21.430765+00', '80', '{"length":15,"width":4,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('c24ddb8a-7ac6-4217-829d-9fd78c1ee7ba', 'Mangueira 10m trama de nylon', 'Nação Detail', 'Acessórios', '300', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQXx1xpXntxVfjUw62rVr9cZc5_Zju4BX02rc3qcPGpsw&s', 'A Mangueira 10m Trama de Nylon da Nação Detail é uma mangueira de alta pressão de premium, com reforço em trama de nylon para máxima resistência à pressão e à abrasão. Com 10 metros de comprimento, proporciona alcance confortável em todos os pontos do veículo sem necessidade de reposicionar a lavadora. Conexões de qualidade e encaixe universal. Ideal para uso profissional diário.', NULL, '2026-07-22 11:31:11.093007+00', '1500', '{"length":30,"width":30,"height":10}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('9467a8c9-6bad-4626-a5fa-a434601c0af7', 'conjunto filtro e mangueira snow foam', 'Nação Detail', 'Itens de reposição', '45', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQuIoboAoq832m1GjCFJTX_BYcHx4GYvNSwo8BR6cVcGA&s=10', 'O Conjunto Filtro e Mangueira Snow Foam da Nação Detail é um kit completo que inclui filtro de água e mangueira especialmente desenvolvidos para o uso em canhões de espuma ativa. O filtro remove impurezas da água, garantindo espuma mais densa e eficiente, enquanto a mangueira proporciona conexão segura e flexível. Ideal para maximizar a performance do seu snow foam.', NULL, '2026-07-19 12:17:21.430765+00', '500', '{"length":30,"width":15,"height":10}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('2b5dc5d8-8703-4938-b6b5-b6513043ebb3', 'Aromatizante seco - Gold', 'Areon', 'Aromatizantes', '15', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQj-zItax3We7sEbrVfh4x8n30BMwhCQoeWrZXHQEbbGw&s=10', 'Ref: EST-ARO-005\nAroma: cítrico, amadeirado e especiarias. Médio.', NULL, '2026-06-24 18:32:32.518561+00', '25', '{"length":12,"width":5,"height":2}', 'Inativo') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('9a8fdf9d-1bb5-484a-8f9c-24970c124d38', 'Aromatizante wild cherry', 'Little Trees', 'Aromatizantes', '20', 'data:image/jpeg;base64,', 'O Aromatizante Wild Cherry da Little Trees é uma fragrância frutal e encantadora com aroma de cereja madura. Doce, marcante e vibrante, transforma o habitáculo do veículo em um ambiente cheio de personalidade. Com até 7 semanas de duração e a praticidade do formato palheta, é a escolha perfeita para quem gosta de aromas intensos e marcantes.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('d2b774f7-9b71-4077-8519-cf90c3da1f60', 'adaptador karcher k', 'Nação Detail', 'Acessórios', '55', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ2pdAbp5PskqNlgbT-nfdNTlyjpOCApfzmnXY5u80UzQ&s', 'O Adaptador Karcher K da Nação Detail é um acessório de alta qualidade desenvolvido para conectar mangueiras e acessórios compatíveis com a linha K de lavadoras de alta pressão Karcher. Fabricado em material resistente e durável, garante vedação perfeita e fluxo de água eficiente durante a lavagem profissional. Facilita a troca rápida de acessórios sem perda de pressão, otimizando o tempo do detailer. Compatível com as principais lavadoras da série K.', NULL, '2026-07-19 12:17:21.430765+00', '120', '{"length":15,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('2fc1973a-dc6f-4a0b-8e5b-6f54f618c1a6', 'atomic paste 100g', 'Cadillac', 'Ceras', '82.4', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/m6h7zmsqb4e1789066648735.webp', 'O Futuro da Proteção Automotiva é Atomic !Chegou a Atomic Past, a cera que une o que há de mais moderno em proteção, brilho e tecnologia para a pintura do seu carro.Com fórmula 100% sintética e tecnologia baseada em SiO2 (dióxido de silício), ela forma uma película ultra reflexiva, de toque sedoso e com uma durabilidade impressionante de até 8 meses.', NULL, '2026-09-10 18:57:30.216239+00', '187', '{"length":13,"width":6,"height":13,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('c894ecb6-5d95-422b-80ac-57c7b4d71c1b', 'Aromatizante vanilla aroma (USA)', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRbGzITTtAbDFySC5wAmou04dIlNN7qApt4SgkUdpoINg&s=10', 'O Aromatizante Vanilla Aroma USA da Little Trees é uma fragrância quente e envolvente de baunilha americana, reconhecida mundialmente pela sua suavidade e sofisticação. Ideal para quem busca um aroma confortante e elegante no interior do veículo. Com durabilidade de até 7 semanas e instalação descomplicada, é presença garantida nos melhores kits de detalhamento.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('8ca2d70c-5617-41f4-bd67-2fa23ed4f24f', 'Black berry 500ML', 'Magil Clean', 'Pneus e rodas', '67.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRGrYH18i91cCen71ZHj56yRzkrKmx-VrJlVJtKV6tnAQ&s', 'O Black Berry da Magil Clean é um revitalizador de pneus de alto desempenho, formulado para proporcionar brilho intenso e duradouro com efeito molhado profissional. Sua fórmula à base de polímeros protetores revitaliza a borracha, combate o ressecamento e protege contra raios UV e agentes oxidantes. Indicado para todos os tipos de pneus de passeio e utilitários, com aplicação simples e resultado imediato.', NULL, '2026-07-21 10:59:41.772855+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1739d1bb-5a2a-4d58-80ca-038037ecbb9d', 'Aplicador magic hand', 'Kers', 'Aplicadores', '29.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSYeQyc3HegHAac8oZNGqqDkfiH-E8yFEXdcW9lGL6_PA&s=10', 'O Aplicador Magic Hand da Kers é um inovador aplicador com design ergonômico que permite a aplicação de ceras, selantes e renovadores sem esforço e sem sujar as mãos. O cabo embutido garante firmeza e controle durante o processo, proporcionando distribuição homogênea do produto na pintura. Compatível com o refil Magic Hand, pode ser reutilizado inúmeras vezes. Indicado para profissionais e entusiastas que valorizam praticidade e higiene.', NULL, '2026-07-21 10:59:41.772855+00', '80', '{"length":18,"width":12,"height":6}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6394f108-741a-4954-984e-552e434bb818', 'Aromatizante melancia', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS5uw6_6dTTxt0c8zti4eJuCJIFJGHernaR4Y64ac1emw&s=10', 'O Aromatizante Melancia da Little Trees é uma fragrância doce, frutal e refrescante que transforma o interior do veículo em um ambiente leve e alegre. Com notas de melancia madura, é a escolha perfeita para os dias quentes, proporcionando frescor e bom humor a cada viagem. Duração de até 7 semanas com instalação prática.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('23303486-9576-42a6-9231-007ec8377715', 'Aromatizante new car scent', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT6tndL8_ILPeHRbG6hoU0m2xv4bAx_BLFLnwI2RFRwWQ&s=10', 'O Aromatizante New Car Scent da Little Trees reproduz com fidelidade o inconfundível aroma de carro zero — aquele cheiro único de interior novo que todos adoram. Com fragrância limpa, levemente adocicada e sofisticada, é a escolha dos que desejam reviver a sensação de estrear o veículo. Uma das fragrâncias mais amadas pelos entusiastas automotivos. Duração de até 7 semanas.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('31a01f36-cf48-44a8-bef6-f72e9b4d5827', 'Aromatizante pina colada', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTQXtzVjY5yoC39CR4EB37sOYA5UlcmPUikrYWv1SEBDA&s=10', 'O Aromatizante Piña Colada da Little Trees traz o prazer dos trópicos para o interior do seu veículo, com sua fragrância doce e exótica de abacaxi, coco e baunilha. Perfeito para os amantes de aromas tropicais e festivos, cria uma atmosfera relaxante e alegre a cada viagem. Duração de até 7 semanas com instalação simples no espelho.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('2e53cfaa-9e98-4b13-a8d9-69cdc53a6b97', 'Toalha de microfibra 40x60cm amarela sem costura', 'Auto América', 'Toalhas', '9.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRnyIuGrHEV7dpy84N6y2o1D4-HlYUSgq2CFnrFI0uK1A&s', 'Toalha de microfibra amarela 40x60cm para secagem, remoção de ceras e limpeza geral.', NULL, '2026-07-22 11:57:18.473555+00', '140', '{"length":62,"width":42,"height":2,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('45ed8118-0a9f-4c72-aced-21838931f17c', 'Aromatizante nemorning fresh', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRWwVIwYejOr_kLW8mC87f1VzO7LEhXfyzJjJp9ByNb2w&s', 'O Aromatizante New Morning Fresh da Little Trees é uma fragrância limpa e revigorante que captura o frescor da manhã com notas aquáticas e florais delicadas. Ideal para quem inicia o dia precisando de energia e leveza, transforma o habitáculo em um espaço de bem-estar. Longa duração e fácil instalação.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
