INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('b47a93d5-eca5-4e21-acaa-56c6e0ba9e03', 'TOALHA DE SECAGEM 90X60CM TWIST', 'KERS', 'Toalhas', '59.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/bwovj3d71op1788791054272.webp', 'A Toalha de Microfibra Twist Cinza 90x60cm 600gsm Kers é a escolha ideal para quem busca eficiência na secagem de veículos. Composta por microfibras de alta qualidade, esta toalha minimiza o atrito com a superfície do carro, evitando riscos e danos à pintura. Sua gramatura de 600gsm proporciona um excepcional poder de absorção, permitindo que você seque seu automóvel de forma rápida e eficaz.', NULL, '2026-09-07 14:24:15.512957+00', '360', '{"length":27,"width":25,"height":5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('38d10894-4a8d-4b1c-bacf-b68619e05461', 'Escova para limpeza de pneus', 'Vonixx', 'Escovas e pincéis, Pneus e rodas', '29.6', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQcWBW56CAFXhPNNO5IOj-QdL3S8eCvfgz7bbNwjw1UsQ&s=10', 'A Escova para Limpeza de Pneus da Vonixx é uma ferramenta de alta eficiência para remoção de sujeira, barro e resíduos incrustados nos pneus e frisos. Suas cerdas resistentes e o cabo ergonômico tornam a limpeza mais rápida e eficiente, preparando perfeitamente os pneus para a aplicação de renovadores e selantes. Resultado profissional com praticidade.', NULL, '2026-06-24 18:32:32.518561+00', '89', '{"length":32,"width":7.5,"height":25}', 'Inativo') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('da6d93a8-f677-4b6c-856a-fd065b681ede', 'Metmol 500ml', 'Jaça', 'Lava auto', '26.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSCzyyGHI_KZR7vsbYYbicCg_3wmWepJvHLemVGlkGFmQ&s=10', 'O Metmol da Jaça é um limpador e renovador especial para superfícies metálicas, cromadas e de alumínio, desenvolvido para remover oxidação, manchas e escurecimento de metais automotivos. Sua fórmula de ação química suave e levemente abrasiva restaura o brilho e o aspecto original de cromados, aros, grades e detalhes metálicos sem danificar as peças.', NULL, '2026-07-21 10:59:42.780268+00', '580', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('eb85c203-ed90-4a04-a84d-f201754e7c26', 'Snow foam manual viton', 'SGT TOOLS BY SIGMA', 'Equipamentos', '120', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT8YSSbQZawkSYUeg94hoT6G3yV7sO1IO2ZwL7XW18qbA&s=10', 'O Snow Foam Manual Viton da By Sigma é um canhão de espuma ativa premium, fabricado com selos e vedações em Viton — material de alta resistência a produtos químicos agressivos. Proporciona espuma extremamente densa e durável, compatível com os shampoos snow foam mais concentrados do mercado. Construção premium para uso profissional intensivo e longa durabilidade.', NULL, '2026-07-19 12:17:20.998748+00', '700', '{"length":25,"width":12,"height":12}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('5c2afff0-1f52-4cf6-94cb-ce233e89244e', 'Extreme 5L', 'Auto América', 'Lava auto', '89.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSD7NuFTUaTNbytGw2fB6zwR1CJtHdCzex7Ys9hWJ9nLg&s=10', 'O Extreme 5L da Auto América é a versão econômica do shampoo automotivo concentrado de alto desempenho, ideal para lava-rápidos, detailers e entusiastas de alta frequência de lavagem. Com rendimento excepcional, uma única embalagem de 5 litros resulta em centenas de lavagens completas. Formula eficaz na remoção de sujeira sem agredir proteções existentes.', NULL, '2026-07-22 11:31:11.093007+00', '5500', '{"length":18,"width":18,"height":31}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('a16bedb8-f1a9-46ff-9aca-ec087103d2c2', 'adaptador wap fino', 'Nação Detail', 'Acessórios', '55', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTLIIpDyrxSs5zfJwI9NFtjhw2HbB0lcD64WDDr7NcNOw&s', 'O Adaptador WAP Fino da Nação Detail foi desenvolvido especificamente para conectar acessórios de lavagem às lavadoras de alta pressão da linha WAP com bocal fino. Proporciona encaixe seguro, sem vazamentos, e permite a utilização de pistolas, snow foams e outros acessórios compatíveis. Essencial para otimizar o processo de pré-lavagem e limpeza profissional com máxima eficiência.', NULL, '2026-07-19 12:17:21.430765+00', '100', '{"length":15,"width":4,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0b363a75-c841-40c9-8080-db7103b766a7', '4X Speed shine tire clear', 'Soft 99', 'Pneus e rodas', '89.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSHdvHUz7mbKwSVTS_Lh3wfJp-p1cM5tIyg8VML7Ry7rg&s', 'O 4X Speed Shine Tire Clear da Soft 99 é um limpador e selante de alto desempenho para pneus, desenvolvido com tecnologia japonesa reconhecida mundialmente. Sua fórmula avançada remove sujeira, graxa e resíduos acumulados, devolvendo ao pneu a aparência de novo com acabamento impecável. Após a aplicação, forma uma camada protetora com brilho profissional e duradouro, resistente à água e aos agentes contaminantes da estrada. Indicado para todos os tipos de pneu — passeio, SUV e pickup — e de fácil aplicação em spray, sem necessidade de polimento. Resultado instantâneo, visual imponente.', NULL, '2026-06-24 18:32:32.518561+00', '420', '{"length":6.5,"width":6.5,"height":22}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1a46e707-9b0f-45fc-8b5d-0b48b2ec8969', 'aplicador espuma pequeno', 'Zacs', 'Aplicadores', '3', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRWL4fumpYFj56lQ0DRgU1zg_mhEUDTNrEeJ37Wdmw5qw&s', 'O Aplicador de Espuma Pequeno da Zacs é ideal para a aplicação de ceras, renovadores, polidores e selantes em superfícies menores e detalhes do veículo. Seu tamanho compacto facilita o acesso a áreas de difícil alcance, como frisos, molduras e logotipos. A espuma de qualidade garante distribuição uniforme do produto, otimizando o resultado final. Prático e econômico.', NULL, '2026-07-21 10:59:42.393339+00', '30', '{"length":10,"width":8,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4708660d-aa8a-4f74-b08f-9235ba1bf76b', 'Black lemon 500ml', 'Jaça', 'Pneus e rodas', '69.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQLOcnTJ2VUq8oJwEIhcn5Sef4Bio83XvUlfOWusWt0Sg&s=10', 'O Black Lemon 500ml da Jaça é um revitalizador de pneus com fragrância cítrica fresca, formulado para devolver o brilho e a aparência de novo aos pneus de qualquer veículo. Sua fórmula com componentes protetores repele a água e os raios UV, prolongando a vida útil da borracha. Acabamento intenso com efeito molhado de alta durabilidade. Aplicação simples e resultado imediato.', NULL, '2026-07-19 12:17:20.432966+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
