INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('fce6cd04-52b9-4f7e-8fe7-f13f201b6ede', 'Tyrant 240ML', 'Razux', 'Motocicletas', '28.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRCzER3YY-Gk1bkhMaFbiwjJQhJ5fvUTw0GkLpzkADf3w&s=10', 'O Tyrant da Razux é um produto especializado para motocicletas com fórmula de alta concentração para limpeza e proteção profunda de superfícies específicas das motos. Remove sujeira, óleo e graxa de forma eficiente, enquanto deposita uma camada protetora que preserva o aspecto original das peças. Resultado profissional para quem leva a sério o cuidado com a moto.', NULL, '2026-07-21 10:59:42.393339+00', '289', '{"length":5.16,"width":5.16,"height":20}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('106a7ec8-a72f-46f0-ae4c-aa01eee7b0c3', 'all clean 1,5L', 'Auto América', 'Limpadores', '37.5', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/t0hds6jt261784632586726.png', 'O All Clean da Auto América é um limpador multiuso de alto poder de penetração, formulado para remover sujeiras, gorduras, resíduos e incrustações de diversas superfícies automotivas — interior e exterior. Sua fórmula versátil é segura para uso em painéis, estofados, plásticos, borrachas e tapetes, facilitando a limpeza completa do veículo em um único produto. Com diluição ajustável, adapta-se desde limpezas leves de manutenção até higienizações mais intensas.', NULL, '2026-07-21 10:59:42.393339+00', '1650', '{"length":10,"width":10,"height":28}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('f002257d-a2f6-4c0b-8b8c-d33f39afa64a', 'v-eco pro 1,5L', 'Vonixx', 'Limpadores', '73.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRYrUuCSbT4Ojm3zkXDGex2sa9fVuuVN1RRlILxo0aLOQ&s=10', 'O V-Eco Pro da Vonixx é um limpador ecológico premium de alta concentração, desenvolvido para a limpeza profunda de interiores e exteriores do veículo. Sua fórmula biodegradável e concentrada oferece performance superior mesmo em sujeiras mais difíceis, sendo segura para todos os tipos de superfície. A escolha sustentável e profissional.', NULL, '2026-07-21 10:59:42.393339+00', '1599', '{"length":9.5,"width":9.6667,"height":31}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3d9c97fe-1197-4727-a428-d3b35ad819e6', 'LAVA AUTO CREMOSO 5l', 'Magil Clean', 'Lava auto', '69.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTIGdEFi9tJM-2o8ND64CrYKfP7s13YCtQccVERa1mSSQ&s=10', NULL, NULL, '2026-07-21 10:59:42.393339+00', '5500', '{"length":18,"width":18,"height":31}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('35ac2094-0d70-4209-bae0-572e2e3e8a5f', 'black boost AEROSOL 400ML', 'DubBoys', 'Verniz', '49.5', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQS18lTn0rD51ALMzS0dxPLAqW4-SvZ2Z0DWqouFM3PPg&s=10', 'O Black Boost da DubBoys é um revitalizador de verniz e plásticos de alta concentração, desenvolvido para escurecer e intensificar a cor de peças plásticas externas, painéis, pneus e superfícies de borracha. Sua fórmula de penetração profunda age diretamente na estrutura do material, proporcionando resultado duradouro e resistente à água. Indicado para bumpers, para-choques, molduras e caixas de roda.', NULL, '2026-07-21 10:59:42.393339+00', '460', '{"length":6.5,"width":6.5,"height":22,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('7c53665b-1ef3-4ec3-a0ae-54bbd3127ee7', 'verom 1,5L', 'Vonixx', 'Verniz', '79.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRDuN5VFGB1qxLHtMOp8CzzgWmrYuE5aT57GQJR9Qd4Bw&s', 'O Verom da Vonixx é um vitrificador de verniz de alto brilho para o setor de acabamento de veículos recém-pintados, proporcionando uma camada protetora de alta dureza e brilho profundo. Sua fórmula avançada é aplicada após o polimento final para selar e proteger a pintura recém-corrigida com durabilidade superior. Acabamento espelhado e proteção profissional.', NULL, '2026-07-21 10:59:42.393339+00', '1650', '{"length":10,"width":10,"height":28}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('9086fade-8579-4fd1-8c96-9a8beb4ed95d', 'All vision 500ML', 'Jaça', 'Vidros', '24.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJ12Awi-AnKoQ6k4JHtZTuCadaiKGmgzmQLjMp-uCWGA&s=10', 'O All Vision da Jaça é um limpador de vidros de alta eficácia, formulado para remover gorduras, insetos, poeira e névoa oleosa de parabrisa, vidros laterais e retrovisores. Sua fórmula de ação rápida evapora sem deixar manchas ou resíduos, garantindo visibilidade cristalina e segurança ao volante. Indicado para uso profissional e doméstico, sendo compatível com qualquer tipo de vidro automotivo.', NULL, '2026-07-21 10:59:41.772855+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('12b5c954-a742-4a36-b9ee-27c3562d238e', 'Foam gloss 5L', 'Magil Clean', 'Lava auto', '169.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRa_mdQ36g2ISgGFyWaHee81fVExDbNLEJiZDWcZPCWDA&s', 'O Foam Gloss 5L da Magil Clean é a versão profissional e econômica do shampoo snow foam de alta concentração, desenvolvido para lava-rápidos e detailers de alto volume. Com rendimento excepcional, uma embalagem de 5 litros é suficiente para centenas de lavagens completas. Produz espuma densa e brilhante, proporcionando eficiência máxima no processo de pré-lavagem sem contato.', NULL, '2026-07-22 11:31:11.093007+00', '5000', '{"length":18,"width":18,"height":31,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('01374c4a-013a-4396-90ca-bdb92a766c96', 'Hydrox fast 500ml', 'Vonixx', 'Ceras', '37.7', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS9Cr356RpzAYjaM1EHTjBfLX_dCsdphvUkVlm-phjQYA&s=10', 'Revestimento cerâmico (coating) hidrorreativo em spray, desenvolvido para proteger a pintura, vidros e plásticos automotivos. Dura até 10 meses.', NULL, '2026-06-24 18:32:32.518561+00', '595', '{"length":6.56,"width":6.37,"height":28.5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4c101950-7171-4ce1-a947-f89f392c650b', 'Pincel super soft', 'Kers', 'Escovas e pincéis', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQ6o59P2ckLmGxB5CweTkl3Zz-Q2Cgml1zORsu09EPYCQ&s=10', 'O Pincel Super Soft da Kers é um pincel premium de cerdas extremamente macias de alta densidade, desenvolvido para o detalhamento de interiores luxuosos e superfícies de alto valor. Limpa com precisão e delicadeza máximas em telas de infotainment, instrumentos digitais, couro napa e outros acabamentos premium. A escolha dos detailers mais exigentes.', NULL, '2026-07-19 12:17:20.841073+00', '60', '{"length":22,"width":4,"height":4,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('36da87a5-d66c-49ec-8cde-061d1cb61df3', 'Vitrificador Glass Coat H7 27ML', 'Soft 99', 'Vitrificador', '104.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQTeI6eEBKYU0jBR7riM8__ZEQEVF0RZQFtCVfDs6j6fA&s=10', 'O Vitrificador Glass Coat H7 da Soft 99 é um vitrificador de vidros de tecnologia japonesa de última geração, que cria uma camada de sílica fundida sobre o parabrisa, formando uma proteção extremamente dura e duradoura. Proporciona hidrofobia de longa duração — a água escorre em gotas esféricas — melhorando a visibilidade e a segurança na condução sob chuva intensa.', NULL, '2026-07-21 10:59:42.780268+00', '80', '{"length":4,"width":4,"height":12}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0e6679d3-9178-4e36-bbf8-3b440387744c', 'Pincel detalhamento médio interno 14', 'Zacs', 'Escovas e pincéis', '9.8', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQBoJB6ZtFONsRBN20hhehoJr5WdCpArPDsSUWZ_RdyJw&s', 'O Pincel de Detalhamento Médio Interno 14 da Zacs é uma ferramenta essencial para o detalhamento interno de veículos, desenvolvida para alcançar com precisão saídas de ar, costuras de bancos, botões e demais áreas de difícil acesso no interior do carro. Cerdas macias e resistentes garantem limpeza eficiente sem arriscar superfícies delicadas.', NULL, '2026-07-21 11:05:04.466452+00', '100', '{"length":20,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('28ed4940-420c-4e47-8430-38d19500249a', 'HPF 500g', 'Lincoln', 'Polimento', '120', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSIo5F8YTYPa5wWT0qwhbGBLKoadFH3_cmmKD0U6EEYgA&s=10', 'O HPF 500g da Lincoln é um composto de polimento de alta performance para lustro e acabamento final, desenvolvido para eliminar as marcas deixadas pelo processo de corte e revelar o brilho máximo da pintura. Sua fórmula abrasiva fina proporciona acabamento cristalino sem efeito holograma, sendo o parceiro ideal após o uso de compostos de corte.', NULL, '2026-07-21 11:05:04.466452+00', '600', '{"length":8,"width":8,"height":10,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('91114e4f-c571-4de5-89fc-e48f4b7dcd25', 'Fast Grafeno 500ML', 'Alcance', 'Selante sintético', '56', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRGJ9k1RoBMmEAKBniEpOD73MId6PwsdvCXH4M3hY-Guw&s=10', 'O Fast Grafeno da Alcance é um selante sintético de última geração com tecnologia de grafeno, desenvolvido para proporcionar proteção de alto desempenho com facilidade de aplicação. O grafeno potencializa a durabilidade, a hidrofobia e a resistência química da proteção, oferecendo um resultado que rivaliza com produtos de preços muito superiores. Brilho intenso e durabilidade prolongada.', NULL, '2026-07-21 10:59:42.780268+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('ff53863f-f752-47ec-90c7-3dcece609e7d', 'aplicador microfibra pequeno', 'Vonixx', 'Aplicadores', '11.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSxFl0fbdUC5hnTdGVg2NwP4ndZgEWmN8RZqGanHyT3ug&s=10', 'O Aplicador de Microfibra Pequeno da Vonixx é o parceiro ideal para a aplicação detalhada de ceras, selantes e protetores em superfícies reduzidas. Fabricado com microfibra macia de alta qualidade, não arranha a pintura e distribui o produto com precisão e uniformidade. Seu tamanho compacto facilita o trabalho em frisos, soleiras e espelhos. Lavável e durável.', NULL, '2026-07-21 10:59:42.393339+00', '40', '{"length":10,"width":8,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('78834d81-bf60-462b-9e46-6462430e3b70', 'Restorfix 500ml', 'Alcance', 'Plásticos', '72', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTCD_EkowAjI3iWBhN36MPA_ueSwggfRiALaIvz6bv4Dg&s=10', 'O Restorfix da Alcance é um restaurador e protetor de plásticos externos de alta performance, desenvolvido para revitalizar para-choques, molduras e caixas de roda intensamente desbotados pela ação do sol e do tempo. Sua fórmula de penetração profunda devolve a coloração original do plástico e forma uma barreira durável contra novos desbotamentos por UV.', NULL, '2026-07-21 10:59:42.780268+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('26d9d657-4a42-422f-b2b8-542e1d096bdb', 'Carbon Black 500ML', 'Jaça', 'Plásticos', '66.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR_QBWY8ozOZRqhzDxWcEi5fZFjUoyj09D05D9o6lPIsQ&s=10', 'O Carbon Black da Jaça é um renovador de plásticos externos de alto desempenho, formulado para revitalizar e escurecer para-choques, molduras, caixas de roda e outros plásticos que sofreram desbotamento pelo sol. Sua fórmula penetra profundamente nas fibras do plástico, devolvendo a coloração original intensa e protegendo contra novos danos causados pela radiação UV. Efeito duradouro e resistente à lavagem.', NULL, '2026-07-21 10:59:42.780268+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('98d7d83d-c64c-478c-93dc-405e1e9aab4e', 'Conector de mangueira lavadora de alta pressao WAP 4000psi', 'KERS', 'Acessórios', '42.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSXnnT-BUaKdJS2_SAxCfDz0FkIPc7lg-48O08rSkNExw&s=10', 'O Conector de Mangueira para Lavadora WAP 4000PSI da Nação Detail é compatível com as principais lavadoras de alta pressão da marca WAP, oferecendo encaixe preciso e vedação confiável em todas as condições de uso. Suporta pressões de até 4000 PSI, sendo essencial para quem busca segurança e eficiência no processo de lavagem profissional.', NULL, '2026-07-21 11:05:04.466452+00', '150', '{"length":15,"width":5,"height":5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('711a3593-8475-403e-b34b-7e05758f1bcd', 'Toalha microfibra Dual Loop 40x60cm 360gsm laranja sem borda', 'Kers', 'Toalhas', '13.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTH6fbIrnlWgwP_s-TyLqC5vJKwyIb5Ly1MIlEwSt28aw&s', 'A Toalha de Microfibra Dual Loop 40x60cm 360gsm Laranja Sem Borda da Kers é uma toalha de grandes dimensões para secagem, remoção de produtos e acabamento final. O formato 40x60cm e a gramatura 360gsm equilibram absorção e maciez, enquanto a construção sem borda elimina o risco de marcas na pintura. Versátil e durável para uso profissional.', NULL, '2026-07-21 10:59:42.780268+00', '160', '{"length":62,"width":42,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('406d68e6-00dd-4aa8-8a29-327f7f067c98', 'kit engate rápido completo 1/4 BSP (macho) com registro e tubeira', 'Nação Detail', 'Acessórios', '299', 'data:image/jpeg;base64,', NULL, NULL, '2026-07-21 10:59:42.780268+00', '300', '{"length":20,"width":10,"height":8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('546aa3c0-8f33-4282-b9ab-a3e6cf17b574', 'Escova para limpeza de boinas', 'Kers', 'Escovas e pincéis, Polimento', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEebqvtirXI17aV0LeZdcp3O7p8D6xXp9BMMhrfLN20Q&s', 'A Escova para Limpeza de Boinas da Kers é um acessório indispensável para manter os pads de polimento sempre em perfeitas condições de uso. Ao ser utilizada durante o polimento, remove o excesso de composto acumulado na boina, liberando os poros e mantendo a eficiência abrasiva em todo o processo. Após o uso, auxilia na limpeza completa para lavagem posterior.', NULL, '2026-07-21 10:59:42.780268+00', '42', '{"length":12,"width":24,"height":18.5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('61b0f437-bdd1-4540-bcf3-87f9cafc56b7', 'Aromatizante green apple', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSei48VJlqJ8XBYYm72QHq6dHxeDhKgC6udE5hH4qONfw&s', 'O Aromatizante Green Apple da Little Trees é uma fragrância frutal, fresca e energizante com aroma de maçã verde. Proporciona um ambiente leve e revitalizante no interior do veículo, ideal para longos trajetos ou uso diário. Com até 7 semanas de duração e design prático para o espelho retrovisor. Perfeito para quem aprecia aromas joviais e refrescantes.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('96f35eef-280a-4337-b45b-ac9039cd5e81', 'Black moon 500ml', 'Jaça', 'Pneus e rodas', '58', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSjCBotiIo0e2DnRMvexTET5Vlcrg9B6ZAILJLW8S_CDA&s=10', 'O Black Moon 500ml da Jaça é um selante de pneus de alto brilho, formulado com polímeros protetores de última geração para proporcionar acabamento intenso com efeito molhado. Protege a borracha dos raios UV, do ressecamento e dos agentes contaminantes da estrada, prolongando a vida útil dos pneus. Durabilidade superior a produtos convencionais, mantendo o resultado por mais tempo após cada aplicação.', NULL, '2026-07-19 12:17:20.432966+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('fa14b6af-f5af-494c-be4e-42934ab2318b', 'Ultra limpador 5L', 'Magil Clean', 'Limpadores', '139.9', 'data:image/jpeg;base64,', 'O Ultra Limpador 5L da Magil Clean é o limpador multiusos profissional de alto desempenho em formato econômico para uso diário em estéticas, lava-rápidos e garagens. Com excelente custo-benefício por litro, proporciona limpeza profunda e eficiente de qualquer superfície automotiva ou industrial. Diluição ajustável para diferentes níveis de sujeira.', NULL, '2026-07-22 11:31:11.093007+00', '5500', '{"length":18,"width":18,"height":31,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1531a2d0-1e08-45e1-9170-3eda5eae05c2', 'Antiembaçante gel 80ml', 'Soft 99', 'Vidros', '59', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRJgrYbvjDai8NS5AHVQlmHSmm4BamDDLL6tIMISLSFNQ&s=10', 'O Antiembaçante Gel 80ml da Soft 99 é uma solução japonesa de alta tecnologia para eliminar o embaçamento interno de vidros e retrovisores. Sua fórmula em gel cria uma película invisível que repele a umidade e impede a formação de névoa, garantindo visibilidade plena em dias frios e chuvosos. De aplicação simples e longa durabilidade, é indicado para parabrisa, vidros traseiros e câmeras de ré. Uma aplicação protege por semanas.', NULL, '2026-06-24 18:32:32.518561+00', '134', '{"length":4,"width":12.3,"height":21.8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('821f6f19-fd58-4edd-953d-d5595e8d9e75', 'Aplicador espuma pacote 2 unid', 'Vonixx', 'Aplicadores', '9.8', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT1IArpIppmdLERSW0sjK-n8-v9_lnL1skD6uOtZhm5fg&s=10', 'O Aplicador de Espuma Vonixx (pacote com 2 unidades) é a escolha certa para a aplicação precisa de ceras em pasta, selantes líquidos e renovadores em geral. Confeccionado em espuma de células fechadas de alta densidade, absorve o produto na medida certa e distribui de forma uniforme sobre a pintura. Leve, resistente e de fácil limpeza, é um must-have para qualquer kit de detalhamento.', NULL, '2026-06-24 18:32:32.518561+00', '60', '{"length":12,"width":10,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('83815334-01e6-43ba-a636-fbd2b1022af1', 'Aromatizante fresh shave', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRj9Ije0l8LWLeLeMoDBeZLEGna-MY28u1Nkn_kMLydRA&s', 'O Aromatizante Fresh Shave da Little Trees oferece uma fragrância limpa, sofisticada e masculina, inspirada no aroma de um barbeador recém-aplicado. Com notas frescas e amadeiradas, cria uma atmosfera refinada no interior do veículo. Durabilidade de até 7 semanas e instalação simples. Ideal para quem aprecia um aroma clássico e elegante.', NULL, '2026-07-21 11:05:04.466452+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('dac54c9e-f05b-4bfe-affc-9b48555b5fa9', 'Aromatizante gold', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTIaPTQBCoIH9bsz9WNNey9Iv_x2T-EPB6zyJ0OQV9vTw&s', 'O Aromatizante Gold da Little Trees é uma fragrância premium com notas quentes, amadeiradas e levemente especiadas, transmitindo sofisticação e requinte ao interior do veículo. Com duração de até 7 semanas, mantém o habitáculo perfumado sem exageros. Ideal para quem busca um aroma elegante e marcante para acompanhar cada trajeto.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3d7442a8-aaa9-4d0d-8807-243f51a15295', 'Aromatizante black ice', 'Little Trees', 'Aromatizantes', '20', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcStActhJWb73uj4QjTVUy8_ASq-uvfZ5kcD2_SsFZnIyQ&s=10', 'O Aromatizante Black Ice da Little Trees é um ícone mundial da perfumação automotiva, com seu inconfundível aroma gelado, fresco e masculino. A árvore de papel impregnada com fragrância de longa duração proporciona até 7 semanas de perfume agradável no interior do veículo. Design compacto, instalação simples no espelho retrovisor. Um clássico que nunca sai de moda.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3d3f7736-390b-4ebc-8eed-d7941140d504', 'Aromatizante coca cola  - Fragrância fanta laranja', 'Airpure', 'Aromatizantes', '30', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSfwAq6X_yV_kpJC5C0PzEHZVeOnSsiFn_PBevRKE543w&s=10', 'O Aromatizante Coca-Cola com Fragrância Fanta Laranja da Airpure é uma edição especial que combina o universo das bebidas mais famosas do mundo com a praticidade de um aromatizante de alta qualidade. Com aroma frutal e vibrante de laranja, transforma o interior do seu veículo em um ambiente refrescante e alegre. Perfeito para quem busca personalidade e bom humor no detalhamento do carro.', NULL, '2026-07-21 10:59:41.772855+00', '25', '{"length":12,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('751ea235-3a24-4a26-8dd1-d795118a6fc3', 'Acid foam 500ML', 'Jaça', 'Lava auto', '29.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRhdraJzvvk65ilahefb5VjXuGu4kkd4AoOR8mIwCN-ug&s=10', 'O Acid Foam da Jaça é um shampoo ácido de expansão espumosa formulado para a remoção de depósitos minerais, ferrugem, cimento e calcário em rodas, carrocerias e superfícies metálicas. Sua ação desincrustante penetra profundamente na contaminação, facilitando a remoção sem a necessidade de esforço mecânico excessivo. Ideal para limpezas pesadas realizadas antes do processo de polimento ou tratamento químico. Compatível com pistolas snow foam e pulverizadores. Não contém abrasivos, preservando as superfícies tratadas.', NULL, '2026-07-21 10:59:41.772855+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('71def084-c77d-42b9-8dfc-812d8c813e1c', 'clip para tapete', 'Detailer', 'Acessórios', '55', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQWs_XsQXYcAFjcnKLLwwJ2OA2z9j6u7oTByQZYGUpuoA&s=10', 'O Clip para Tapete da Detailer é um acessório prático e funcional desenvolvido para manter os tapetes do veículo perfeitamente posicionados durante o uso. Evita que o tapete se desloque e prenda o pedal do acelerador, garantindo segurança e conforto ao motorista. Fabricado em material resistente, compatível com a maioria dos veículos e tapetes automotivos. Simples de instalar.', NULL, '2026-07-21 10:59:42.393339+00', '30', '{"length":10,"width":5,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('8aa5ef43-d819-4d61-b580-f766de7c674d', 'conector mangueira hd', 'Detailer', 'Acessórios', '60', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQmsbvBCCWzGxyR7TZAn26-AjMy_cta2px-NJGN9CImKg&s', 'O Conector de Mangueira HD da Detailer é um acessório de alta durabilidade para conexão de mangueiras em lavadoras de alta pressão do segmento semiprofissional e profissional. Com rosca e encaixe reforçados, garante vedação perfeita mesmo em uso intensivo, sem vazamentos e sem perda de pressão. Indicado para detailers que exigem confiabilidade do equipamento.', NULL, '2026-07-19 12:17:21.430765+00', '150', '{"length":15,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('f777e035-616e-4f50-b239-f636109010e6', 'Tricover 20ML', 'Razux', 'Motocicletas, Vitrificador', '69.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRkMhOCucS8k04wZafBZtTrP0qOI0UtdZtb9XFME8PB5A&s=10', 'O Tricover da Razux é um produto multifuncional para motocicletas, que combina ação de limpeza, proteção e renovação em uma única fórmula. Desenvolvido para as superfícies específicas das motos — plásticos, cromados, pintura e borrachas — entrega resultado completo com praticidade e eficiência. A solução all-in-one para o detalhamento de motocicletas.', NULL, '2026-07-21 10:59:42.393339+00', '78', '{"length":10,"width":11,"height":3.5,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1a5b2cac-bf56-49f0-9f12-d09d691e6ec5', 'Aromatizante Areon Smile vanilla', 'Areon', 'Aromatizantes', '30', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTSv7ULTl0zvDTbY5FWCVLUfnEFrmEWM1JdA1O-1Buzig&s', 'O Aromatizante Areon Smile Vanilla é uma fragrância premium em formato palheta para o interior do veículo, com aroma suave e envolvente de baunilha. Desenvolvido com essências de alta qualidade, proporciona perfumação discreta e duradoura, criando uma atmosfera agradável e confortável para motorista e passageiros. Fácil instalação no painel ou espelho retrovisor. Durabilidade de até 45 dias.', NULL, '2026-07-21 10:59:41.772855+00', '80', '{"length":12,"width":8,"height":5}', 'Inativo') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('246bdc17-b7e2-4f91-a5d7-7044c27f6507', 'Black Pro 500ML', 'Alcance', 'Pneus e rodas', '73.6', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRBRRxOsn0xZ8rIx8fACbDT05axz_dgEdcNW6JkcXdT1g&s=10', 'O Black Pro da Alcance é um renovador e selante de pneus de alto desempenho, desenvolvido com tecnologia avançada de polímeros para proporcionar brilho profissional e proteção duradoura. Sua fórmula penetra na borracha, revitaliza a cor e forma uma barreira protetora contra UV, ozônio e intempéries. Indicado para uso profissional em detalhamento completo do veículo.', NULL, '2026-07-21 10:59:42.780268+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('91e6e125-0a5d-4fab-8304-5cdfc7475c35', 'Escova para limpeza de couro com cerdas naturais', 'Kers', 'Escovas e pincéis,Couro', '49.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS7PI1F0hAcOv6pQnLBWr3Vdw54vJOZR0qIdxEpZjOcdw&s=10', 'A Escova para Limpeza de Couro com Cerdas Naturais da Kers é desenvolvida com cerdas naturais macias de alta qualidade, projetadas especificamente para a limpeza de bancos, volante e demais superfícies de couro genuíno e sintético. A suavidade das cerdas garante limpeza eficiente sem arriscar o acabamento delicado do couro. Ideal para usar em conjunto com hidratantes e limpadores específicos de couro.', NULL, '2026-07-21 10:59:42.780268+00', '100', '{"length":20,"width":8,"height":8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('299a88f7-2eef-4ac3-8577-f721256580d8', 'Cadmix 500ml', 'Cadillac', 'Acessórios', '16', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQSwicRafzykRPMDKsPV5i4Ng9MM9tsyVe8sSHWZFhhgg&s=10', 'O Cadmix 500ml da Cadillac é um aditivo para água de lavagem que potencializa a ação do shampoo e melhora a lubrificidade da solução de lavagem. Sua fórmula aumenta a espuma, facilita a remoção de sujeira e protege a pintura durante o processo de lavagem convencional. Ideal para uso em baldes de dois estágios, proporcionando uma lavagem mais segura e eficiente.', NULL, '2026-07-19 12:17:20.432966+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0a77566c-c590-42e1-8f21-5d926348f647', 'Claybar 50g', 'Auto América', 'Descontaminante', '25.4', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSYnz6jF_Tt2CMlkcxZ-nIS7_dy5bmiUi9sgf34IARpeQ&s=10', 'O Claybar 50g da Auto América é um argila descontaminante sintética de alta qualidade para a remoção de contaminantes metálicos, pólen, resina e outras partículas incrustadas na pintura que não saem apenas com a lavagem convencional. Ao deslizar suavemente pela superfície lubrificada, a argila captura e remove esses contaminantes, deixando a pintura lisa como vidro — essencial antes de qualquer processo de polimento ou proteção. Rende muito com uso correto.', NULL, '2026-07-19 12:17:20.432966+00', '90', '{"length":10,"width":6,"height":2,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3899db78-ee6c-4c53-b8c0-0afdaaf3519b', 'ESCOVA DUAL COLOR PARA LIMPEZA DE RODAS E PNEUS', 'KERS', 'Escovas e pincéis', '49.91', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/zkbur6d0llf1788791196250.webp', 'A Escova para Limpeza de Rodas e Pneus Dual Color Kers é a ferramenta ideal para manter as rodas e pneus do seu veículo impecavelmente limpos. Com design ergonômico e cerdas de alta qualidade, essa escova oferece uma limpeza profunda e eficiente, removendo sujeira, poeira e resíduos de freio com facilidade.', NULL, '2026-09-07 14:26:38.729172+00', '135', '{"length":30,"width":6,"height":6,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('36261968-ba2f-44a0-96f7-8d957ee8b632', 'Ecoblack 1,5L', 'Vintex', 'Pneus e rodas', '26.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTTe1N06yjFBonoUj-5tD8Qf-8fv8twkBtIrnOFB24FVA&s=10', 'O EcoBlack da Vintex é um revitalizador de pneus econômico e eficiente, formulado para proporcionar brilho intenso e proteção duradoura com baixo custo por aplicação. Sua fórmula prática e de aplicação rápida é ideal para manutenção regular, mantendo os pneus sempre com visual cuidado e protegidos contra o ressecamento.', NULL, '2026-07-21 10:59:42.780268+00', '1500', '{"length":9.5,"width":9.3,"height":32}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1f04a06c-9215-447a-afed-cba796645bca', 'Blend Spray black  500ml', 'Vonixx', 'Ceras', '49.4', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTlKDWqRZ_QOph4-QkSaiclxAdA-BuFxPVYQ4k9pbL6WA&s', 'A Cera Blend Spray Black da Vonixx foi desenvolvida especificamente para veículos de cores escuras, principalmente pretos. Composta por SiO2 e pura carnaúba tipo 1, esta cera líquida em spray protege, dá um brilho profundo e esconde leves riscos (efeito mascarador), realçando a cor do veículo com alta repelência à água. Duração de até 4 meses.', NULL, '2026-07-24 11:20:54.150097+00', '560', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('51c66210-c028-4855-bef9-66037418c54b', 'BOINA FLAT ESPUMA REFINO/LUSTRO 5.5 AZUL', 'LINCOLN', 'Polimento', '56', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/4moysx7vc7j1788791476635.webp', 'Indicada para roto orbitais e rotativas, oferece estabilidade, menor aquecimento e excelente custo-benefício. Ideal para a etapa de refino e lustro com acabamento profissional. Espuma de poliéster de alta performance.', NULL, '2026-09-07 14:31:17.689447+00', '24', '{"length":24,"width":21,"height":2,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1b5170eb-a8a3-4686-bad6-3498856870e2', 'Boina 5.0 Pirulito CORTE PESADO SEM INTERFACE', 'Lincoln', 'Polimento', '60', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRlTIFMN2NV8KIfGMjtiCt8n6T0gnRuqIcSLEiJfRcENQ&s=10', 'COMPATIVEL COM POLIITRIZ ROTO ORBITAL E ROTATIVA.', NULL, '2026-07-24 11:20:54.150097+00', '150', '{"length":15,"width":15,"height":3,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1e2103b9-066c-495f-ab36-d67b3bc8de2e', 'Boina 5.5', 'Lincoln', 'Polimento', '85', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQIbMgZcQYjSSN8cheeTxiXislXissKweTdj3qyQmty2w&s=10', 'A Boina 5.5 da Lincoln é um pad de polimento profissional fabricado com espuma de alta qualidade, indicado para uso em politrizes rotativas COM INTERFACE. Com corte e acabamento otimizados para o tamanho 5.5 polegadas, proporciona distribuição uniforme dos compostos abrasivos e polidores, garantindo resultado preciso na correção ou lustro da pintura. Durável e lavável, mantém o desempenho após múltiplos usos.', NULL, '2026-07-19 12:17:20.432966+00', '155', '{"length":16,"width":16,"height":4,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('cd2d3d28-c086-49ab-9061-26341d6a1007', 'Conector de mangueira lavadora de alta pressao Bosch e Black Decker 4000psi', 'KERS', 'Acessórios', '42.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQkNeSpYmPT7S9iJ3Kh5UvrDrwOPCIQfgCFoVXd41OMkQ&s', 'O Conector de Mangueira para Lavadora Bosch e Black Decker 4000PSI da Nação Detail é um acessório de encaixe preciso desenvolvido para conectar com segurança mangueiras e acessórios de alta pressão às lavadoras das marcas Bosch e Black Decker. Fabricado em material de alta resistência, suporta pressões de até 4000 PSI sem vazamentos. Compatível com a maioria dos modelos dessas marcas.', NULL, '2026-07-21 11:05:04.466452+00', '150', '{"length":15,"width":5,"height":5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3e39e385-e55a-4e37-bfa4-e215214a0ab3', 'REVERSE 50ML VITRIFICADOR DE PLÁSTICO', 'Jaça', 'Vitrificador', '125', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/hn9vgd9eba71788798749959.webp', 'O Reverse Vitrificador de Plásticos Jaça 50ml é um produto de alto desempenho desenvolvido para restaurar, proteger e revitalizar superfícies plásticas internas e externas do veículo. Sua fórmula avançada cria uma camada vitrificada de longa duração, que devolve o aspecto original das peças, proporcionando brilho intenso e proteção contra raios UV, desbotamento e envelhecimento precoce.\n\nIdeal para plásticos ressecados, para-choques, frisos, retrovisores e outras partes externas, o Reverse forma um escudo protetor que resiste à chuva, ao sol e à ação do tempo. Além de restaurar a cor e o acabamento original, o produto garante efeito hidrorrepelente, toque seco e acabamento de fábrica, sem deixar resíduos oleosos.', NULL, '2026-09-07 16:32:32.921666+00', '180', '{"length":15,"width":15,"height":4,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('7625411c-198c-4f71-957a-bf38935fcb2d', 'Glaco 75ml', 'Soft 99', 'Vidros', '69.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS5zNNB9N3hYX-iUjOtd8sDvjRHuuHYNUZQGa1FqYvJ8Q&s=10', 'O Glaco da Soft 99 é o repelente de água para vidros mais famoso do Japão, reconhecido mundialmente pela sua eficácia incomparável. Sua fórmula de silicone de alta concentração se une quimicamente ao vidro, criando uma superfície ultralisa e hidrofóbica que repele a água com eficiência. A partir de 80 km/h, as gotas deslizam sozinhas pelo parabrisa, dispensando o uso do limpador. Duração de até 6 meses.', NULL, '2026-07-21 10:59:42.780268+00', '125', '{"length":6,"width":15.3,"height":21.8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('375397b1-1fb0-4f85-8781-e4b842179429', 'Conector de mangueira lavadora de alta pressao Karcher serie K 4000psi', 'KERS', 'Acessórios', '42.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTswcoi-sMknEI8dcJzYzaeHKknrBruFFhjXSBQgIYk5A&s=10', 'O Conector de Mangueira para Lavadora Karcher Série K 4000PSI da Nação Detail oferece compatibilidade perfeita com as lavadoras da série K da Karcher, garantindo encaixe seguro e vedação sem vazamentos. Suporta pressões elevadas de até 4000 PSI, sendo ideal para uso profissional em detalhamento automotivo e limpeza pesada.', NULL, '2026-07-21 11:05:04.466452+00', '150', '{"length":15,"width":5,"height":5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('b47ecba1-2ed3-46df-b6fc-154bbdc0703d', 'neon 1,5l', 'Auto América', 'Lava auto', '47.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/7fje675l7yj1789064622439.webp', 'O Neon Autoamérica é ideal para quem busca um produto de alta qualidade e eficiência. Sua fórmula especial permite uma limpeza profunda, removendo a sujeira e a graxa sem danificar a pintura do seu carro. Além disso, deixa um brilho radiante, dando ao seu veículo uma aparência de novo', NULL, '2026-09-10 18:23:44.236174+00', '1591', '{"length":9,"width":9,"height":26,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('36214104-0a30-4378-9d33-41d6286f1f2b', 'Corte liquido step 1 500ml', 'Auto América', 'Polimento', '34.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSZWzvITtIF34SSGbIR0KpeiqgVEdImxVJv3RkKYgAd1A&s=10', 'O Corte Líquido Step 1 500ml da Auto América é um composto de polimento para corte médio, indicado como primeiro passo no processo de correção da pintura. Sua fórmula abrasiva de granulometria controlada remove riscos, swirls, oxidação e imperfeições moderadas com eficiência, preparando a superfície para as etapas de lustro e proteção. Compatível com politrizes orbitais e rotativas.', NULL, '2026-07-19 12:17:20.432966+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0593d4c0-0011-4d7d-84b5-68a471323953', 'carpet clean', 'Kers', 'Itens de reposição', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRZCbwXVAyOJfSnkQJ5Z2HUmTzsVZkERL5DTRs2lgO-EQ&s=10', 'O Carpet Clean da Kers é um limpador especializado para carpetes, tapetes e estofados de tecido, formulado para remover manchas, sujeiras orgânicas, gordura e resíduos incrustados com eficiência. Sua fórmula de ação profunda penetra nas fibras do tecido, agindo na raiz da sujeira para garantir uma limpeza completa e higiênica. Deixa os estofados com aparência renovada, sem resíduos e com secagem rápida.', NULL, '2026-07-19 12:39:30.271359+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('122ade77-3ea2-40fe-b334-231464896445', 'TOALHA BRANCA 40X40 1000GSM', 'Auto América', 'Toalhas', '32.5', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/difdkgfksgg1788788723460.webp', 'TOALHA DE MICROFIBRA BRANCA, ULTRA MACIA SENDO IDEAL PARA RETIRADA DE CERA E LUSTRO FINAL. NAO RISCA, NEM DANIFICA A PINTURA.', NULL, '2026-09-07 13:45:24.784299+00', '211', '{"length":40,"width":40,"height":2,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('2e183da8-75c0-46c4-8541-4c10c84f05ee', 'Breeze snow foam de sucção e gravidade', 'Kers', 'Equipamentos', '199', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRudbZ9BAtGuAw5eS88zUT0pMDPGKKhBV6ORWx9_xOcTg&s', 'O Breeze Snow Foam de Sucção e Gravidade da Kers é um sistema de aplicação de espuma ativa de alto desempenho, compatível com qualquer lavadora de alta pressão. Com duplo sistema de alimentação por sucção e gravidade, oferece flexibilidade máxima no processo de pré-lavagem, produzindo espuma densa e estável que adere à carroceria e age quimicamente sobre a sujeira. Perfeito para detailers que buscam versatilidade e eficiência na lavagem sem contato.', NULL, '2026-07-21 10:59:42.780268+00', '750', '{"length":25,"width":12,"height":12,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('e7a3fe3c-6351-4be8-a9d5-73a8f9dc0d0b', 'BOINA FLAT ESPUMA CORTE LEVE/REFINO 5.5 LARANJA', 'LINCOLN', 'Polimento', '56', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/kl3k1sisrz1788791647309.webp', 'Boina de espuma Laranja Corte Suave é ideal para a etapa de pré refino, para isso possuí uma espuma macia, mas com abrasividade no ponto certo para um trabalho limpo e sem muitas marcas, sendo ideal para corte leves em carros de verniz macio e refino em carros de verniz duro.', NULL, '2026-09-07 14:34:08.461786+00', '24', '{"length":22,"width":20,"height":2,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('23624d79-f63e-4d5c-bc5d-b17928df5abb', 'Glass Refresh', 'Soft 99', 'Vidros', '69', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQTwcGFx1MKyFHFAz5OXwy-Z3dHUP2bCgeglNOWucENug&s=10', 'O Glass Refresh da Soft 99 é um limpador e renovador de vidros de tecnologia japonesa avançada, desenvolvido para remover manchas de chuva ácida, depósitos minerais e contaminação orgânica sem riscos. Sua fórmula abrasiva suave elimina embaçamentos e irregularidades da superfície do vidro, preparando-o para a aplicação de repelentes de água. Visibilidade cristalina e vidros como novos.', NULL, '2026-07-21 10:59:42.780268+00', '158', '{"length":3,"width":14.7,"height":21.7}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3b8f3094-093a-44a3-a64b-c0cd5ea8d92d', 'Bubble foam 500ml', 'Jaça', 'Lava auto', '24.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR8y3dM9TO0TlJCNaBQq9qXGg9h_nKx9p0tXWEBFCImZA&s=10', 'O Bubble Foam 500ml da Jaça é um shampoo snow foam de alta expansão, formulado para gerar espuma densa e estável no processo de pré-lavagem sem contato. Sua ação lubrificante encapsula as partículas de sujeira, evitando que arranhões sejam causados durante o enxágue. Compatível com canhões de espuma e snow foams, proporciona limpeza eficiente e segura da carroceria inteira. Fragrância agradável.', NULL, '2026-07-19 12:17:20.432966+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
