INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6bd4c050-6e5d-4990-b6e1-7718c216628b', 'Boina 6.0', 'Lincoln', 'Polimento', '63', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT58f5EoTPOO8KEM9fE2T07sDwOdglPaS3WCWTqnpzPJA&s=10', 'A Boina 6.0 da Lincoln é um pad de polimento versátil para politrizes orbitais e rotativas, fabricado com espuma de alta densidade para distribuição eficiente dos compostos de polimento. Ideal para operações de corte médio, lustro e acabamento em painéis maiores como capo, teto e portas. Sua construção durável suporta uso intensivo profissional, mantendo a forma e o desempenho ao longo do tempo.', NULL, '2026-07-19 12:17:20.432966+00', '160', '{"length":17,"width":17,"height":4,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('e77b15eb-7d65-4a41-8053-1390d857a0af', 'green apc', 'Auto América', 'Limpadores', '26.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/g4znvucc4tr1789064821695.webp', 'Desenvolvido para oferecer máxima eficiência e segurança, este limpador multiuso está pronto para usar, eliminando a necessidade de diluição e garantindo resultados profissionais com facilidade', NULL, '2026-09-10 18:27:03.287488+00', '605', '{"length":7,"width":7,"height":24,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('43b060a9-6cb5-44f5-8ac2-c06a7bb66716', 'PULVERIZADOR SPEED CLEAN DOUBLE ACTION 2L', 'KERS', 'Equipamentos', '129.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/4bhux0ylzpc1789145956002.JPG', 'O Kers Speed Clean Double Action é um pulverizador de compressão manual profissional, projetado para aplicação de produtos químicos e espumantes com máxima eficiência. Produz uma espuma densa e aderente, garantindo cobertura uniforme e melhor desempenho na limpeza.\n\nBasta adicionar seu shampoo automotivo favorito (não incluso), diluir na proporção correta com água, bombear a alça para gerar pressão e acionar o gatilho para aplicação. A trava no gatilho permite uso contínuo, enquanto a capacidade de 2 litros garante mais autonomia no trabalho.\n\nO leque de 55° amplia a área de aplicação, agilizando o processo e reduzindo o tempo de limpeza.\n\nBenefícios\nEspuma espessa e aderente para melhor ação de limpeza\n\nTrava de gatilho para aplicação contínua\n\nCapacidade de 2 litros, maior autonomia\n\nLeque de 55° que aumenta a área de aplicação e economiza tempo\n\nCompatível com diversos produtos químicos e espumantes', NULL, '2026-09-11 16:59:18.290561+00', '591', '{"length":17,"width":16,"height":34,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('d5e03383-1ad9-476c-92c3-b5f63bb12acc', 'impact 5l', 'Vonixx', 'Desengraxantes e desincrustantes', '73.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRFkRNFgXaL7g8c4pd0pOASfH8C-wUXjOjCuWZNG3euvA&s=10', 'O Impact da Vonixx é um descontaminante ferroso e removedor de sujeiras pesadas de alta concentração, desenvolvido para a remoção de partículas metálicas, freio e outros contaminantes incrustados na pintura, vidros e rodas. Sua fórmula reage visivelmente ao ferro, ficando roxa ao contato com os contaminantes — facilitando o controle do processo. Resultado impressionante sem esforço mecânico.', NULL, '2026-07-21 10:59:42.393339+00', '5517', '{"length":19.25,"width":17.8,"height":30.5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
