INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0cf5ce6b-ebd5-44a0-91dd-bfd24bd03bae', 'foam gloss 1l', 'Magil Clean', 'Lava auto', '59', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSVtGfNnwXGNbslEi-ohM5HnlIggjyMPkSaVaELVMn3ew&s=10', 'O Foam Gloss da Magil Clean é um shampoo snow foam de alta concentração para uso em canhões de espuma ativa, desenvolvido para produzir espuma extremamente densa e estável. Sua fórmula com agentes brilhantes proporciona limpeza profunda e deixa a pintura com aspecto de lustrada após o enxágue. Ideal para pré-lavagem sem contato em veículos com pintura encerada ou selada.', NULL, '2026-07-21 10:59:42.393339+00', '1167', '{"length":10,"width":10,"height":25,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1899daac-5018-4073-a015-d5153c8c659a', 'auto brilho 500ml', 'Auto América', 'Ceras', '49.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/tee4wvj193k1789065007197.webp', 'Auto Brilho Autoamerica é um finalizador desenvolvido para proporcionar acabamento e brilho intenso à pintura automotiva. Ideal para peças recém-pintadas com verniz em processo de evaporação, o produto encobre pequenas imperfeições de forma rápida e eficiente. Sua fórmula isenta de silicone facilita a aplicação e remoção, garantindo um resultado profissional', NULL, '2026-09-10 18:30:08.687885+00', '573', '{"length":6,"width":6,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('42b8cfd7-43f5-4542-b10e-c6ac82c4c3b9', 'ROLO MICROFIBRA 170GSM 30X30 CINZA 50 UNID', 'KERS', 'Toalhas', '119', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/eamzverl7591789146258823.webp', '- 50 Unidades de Flanela: Cada rolo contém 50 unidades individuais de flanela, proporcionando uma solução completa e econômica para suas necessidades de limpeza em larga escala.\n- Dimensões Generosas: Cada flanela possui uma área de 30x30 cm, oferecendo uma cobertura ampla para uma limpeza rápida e eficiente em diversas superfícies.\n- Gramatura de 170gsm: Com uma densidade de 170 gramas por metro quadrado, estas flanelas proporcionam excelente capacidade de absorção de líquidos e partículas de sujeira, garantindo resultados impecáveis em cada aplicação.\n- Composição de Qualidade: Fabricadas com 80% de poliéster e 20% de poliamida, estas flanelas combinam maciez e durabilidade para uma limpeza eficaz e duradoura.\n- Cor Amarela Vibrante: A cor cinza não apenas adiciona um toque de profissionalismo ao ambiente, mas também facilita o uso no dia a dia com a praticidade.\n- Uso Versátil: Ideal para limpeza de superfícies variadas, desde pisos e balcões até vidros e espelhos, estas flanelas de microfibra são indispensáveis em qualquer ambiente doméstico, comercial ou industrial.', NULL, '2026-09-11 17:04:21.768446+00', '869', '{"length":12,"width":12,"height":30,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('edd068ee-1e3f-430f-b027-399327163120', 'Clean dex (diluição máxima 1/20) - alcalino 5L', 'Magil Clean', 'Desengraxantes e desincrustantes', '69.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRDS6GA6JZ_vJH5Bt89bAbiO4ybG86SFaYVTh1uEfshQ&s=10', 'O Clean Dex Alcalino 5L da Magil Clean é um desengraxante de alta performance com diluição máxima de 1:20, desenvolvido para a remoção de óleos, graxas, fluidos automotivos e sujeiras pesadas em motor, rodas, caixas de roda e superfícies industriais. Sua fórmula alcalina de alta concentração proporciona excelente custo-benefício para uso profissional, sendo altamente eficaz mesmo nas condições de contaminação mais severas.', NULL, '2026-07-22 11:31:11.093007+00', '5750', '{"length":18,"width":18,"height":31,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('95167974-41e3-4530-91ca-044eb9a95bf8', 'Escova para limpeza de raios e aros de moto', 'Vonixx', 'Escovas e pincéis, Motocicletas', '35.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRAUgSsMbAF8GXQf2gAqVaVjpw9YkOjxIV3ByGu-cD2cQ&s=10', 'A Escova para Limpeza de Raios e Aros de Moto da Vonixx é uma ferramenta especializada para o detalhamento de motocicletas, desenvolvida para alcançar com precisão os raios, aros e regiões de difícil acesso das rodas. Cerdas firmes e resistentes removem sujeira, graxa e resíduos sem danificar o acabamento cromado ou pintado das rodas. Essencial no detalhamento completo de motos.', NULL, '2026-07-19 12:17:20.432966+00', '150', '{"length":25,"width":8,"height":8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('acb2b1a1-ff24-4c26-9164-95c5c6485041', 'conector de mangueira lavadora de alta pressao dawoo, patriot e black decker 4000psi', 'Kers', 'Acessórios', '42.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQm30mFLOu76IUo2U_B7p5t_gMt5sQ0qnFcE7ehZ-hJ7Q&s', 'O Conector de Mangueira para Lavadoras Daewoo, Patriot e Black Decker 4000PSI da Kers é um acessório indispensável para quem utiliza essas marcas no processo de lavagem e detalhamento automotivo. Com encaixe robusto e vedação eficiente, suporta pressões de até 4000 PSI sem vazamentos, garantindo segurança e performance no trabalho.', NULL, '2026-07-19 12:17:21.430765+00', '150', '{"length":15,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4b3973dc-6e16-4d32-aca6-c7ff6ae0a6ab', 'Diluvio express 500ml', 'Cadillac', 'Selante sintético', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSwFqtV2UC7NVkXDval17nARFVl-XE656XoWB1lTNJj5A&s', 'O Dilúvio Express 500ml da Cadillac é um selante sintético de aplicação rápida para uso no veículo molhado ou seco, proporcionando proteção e brilho imediatos em apenas uma aplicação. Sua fórmula de última geração forma uma camada hidrofóbica eficiente que repele água, sujeira e contaminantes por semanas. Ideal para manutenção rápida entre tratamentos completos.', NULL, '2026-07-19 12:17:20.432966+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('ba8c029f-12a2-495a-9d59-4174e3410ecf', 'Diluvio ultra 500ml', 'Cadillac', 'Selante sintético', '79.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQyLw1QucACg90xWYrLT7sTIR3O7VxzQL8ClSNMaZBk6w&s=10', 'O Dilúvio Ultra 500ml da Cadillac é um selante sintético premium de alto desempenho, formulado com tecnologia avançada de polímeros SiO2 para proporcionar proteção profissional de longa duração. Cria uma barreira hidrofóbica resistente que repele água, lama, sujeira e contaminantes com eficiência superior. Brilho profundo e efeito d''água notável a cada chuva.', NULL, '2026-07-19 12:17:20.432966+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('e37d0790-8313-412f-8f7a-f7f2bec763c6', 'Escova clean tire para Pneus', 'Kers', 'Escovas e pincéis, Pneus e rodas', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSMqEHniTuX3rR9en7IeKxHf2no0tbk2zAW4cUuSQI-AA&s=10', 'A Escova Clean Tire para Pneus da Kers é uma escova de alta performance desenvolvida para a limpeza profunda de pneus, flancos e caixas de roda. Suas cerdas de nylon resistente removem sujeira incrustada, ceras antigas e resíduos sem danificar a borracha. O cabo ergonômico facilita o alcance em todas as posições. Indispensável no protocolo de limpeza de pneus.', NULL, '2026-07-21 10:59:42.780268+00', '150', '{"length":25,"width":8,"height":8}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4b92d5e5-2cbb-4147-9b37-3176c9acc4ee', 'Escova clean chain - escova para limpeza de correntes', 'Kers', 'Escovas e pincéis, Motocicletas', '27', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRb72yGLXOtJbb5tPBTwCulqQ3TDHucKrvMycqi0Gxu_w&s=10', 'A Escova Clean Chain da Kers é uma escova especializada para limpeza profunda de correntes de motocicletas, bicicletas e outros veículos. Suas cerdas resistentes alcançam todos os elos da corrente com facilidade, removendo graxa velha, sujeira e contaminantes com eficiência. O cabo ergonômico proporciona firmeza durante o uso. Essencial na manutenção de correntes.', NULL, '2026-07-21 10:59:42.780268+00', '120', '{"length":22,"width":5,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6cdb3b6f-e929-4684-b030-9a2aeb96a792', 'Escova Softrub para limpeza de couro', 'Kers', 'Escovas e pincéis, Couro', '15.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRv368JoG0W_p-bacfMIqUPA-bHTk06fEwwlZTaVCTXQ&s', 'A Escova Softrub para Limpeza de Couro da Kers é uma escova de cerdas ultra macias, desenvolvida para a limpeza delicada de couros genuínos, sintéticos e alcântara. Sua tecnologia Softrub garante remoção eficiente de sujeira e oleosidade sem causar desgaste ou riscos nas superfícies delicadas. Perfeita para uso com limpadores de couro em bancos, volantes e painéis.', NULL, '2026-07-21 10:59:42.780268+00', '110', '{"length":22,"width":8,"height":6}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('aa024fc3-8705-4a5d-9546-e26e280c3ad4', 'Escova para retirar pelos de estofados', 'Kers', 'Itens de reposição', '35.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRlzwJamwZXih-QmQTJQ1jshwLS1enTdSe4uHX74DGmVw&s=10', 'A Escova para Retirar Pelos de Estofados da Kers é um acessório prático e eficaz para a remoção de pelos de animais, fiapos e partículas de tecido dos estofados do veículo. Sua superfície especial captura os pelos com facilidade, sem danificar o tecido ou couro dos bancos. Limpeza rápida e eficiente para quem transporta pets com frequência.', NULL, '2026-07-19 12:17:20.432966+00', '120', '{"length":22,"width":8,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('947e03cd-153f-4a4c-892e-93c143c26b10', 'Fast cut 1kg', 'Auto América', 'Polimento', '62.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSH-a4txxBEM-1cu7lluJNH2SYeDHCIFNvKdsQHOYbsZg&s=10', 'O Fast Cut 1kg da Auto América é um composto abrasivo de corte agressivo, desenvolvido para a correção de pinturas com danos severos — riscos profundos, oxidação intensa e marcas de fabricação. Sua fórmula de alta performance remove imperfeições com rapidez, reduzindo o tempo de polimento sem comprometer o acabamento. Compatível com politrizes rotativas e orbitais de alta velocidade.', NULL, '2026-07-19 12:17:20.841073+00', '1150', '{"length":12,"width":12,"height":20}', 'Disponível') ON CONFLICT (id) DO NOTHING;
