INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3707a370-2081-41a5-87a8-9101bf8fd2ac', 'Silvert 240ml', 'Razux', 'Motocicletas', '42.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRkPx0geP7msIV4_CnxIDK05C3iE3Kg4C_iD8wWmXv5oA&s=10', 'O Silvert 240ml da Razux é um produto premium desenvolvido para o polimento e proteção de peças cromadas e de alumínio em motocicletas, removendo oxidação e manchas enquanto deposita uma camada protetora de alto brilho. Fórmula específica para o universo das motos, com resultado profissional em formato compacto.', NULL, '2026-07-19 12:17:20.998748+00', '294', '{"length":5.33,"width":5,"height":24}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('695fa799-3d03-410d-b252-478c89bc32be', 'Interior detailer 300ml', 'Auto América', 'Plásticos', '29.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTXk3V96h9cazY3ri0BLnjDmlXcb8R8tw8ogDrVBtlciQ&s=10', 'O Interior Detailer 300ml da Auto América é um limpador e renovador completo para interiores automotivos, desenvolvido para limpar e proteger plásticos, painéis, couro e superfícies vinílicas em uma única aplicação. Sua fórmula com agentes condicionantes elimina a sujeira e deposita uma fina camada protetora, deixando o interior do veículo com aspecto limpo, renovado e levemente brilhante.', NULL, '2026-07-19 12:17:20.841073+00', '360', '{"length":5,"width":5,"height":17,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('c70aec81-bb2b-46b4-bdea-84faf3e91634', 'Snow foam Gravity', 'SGT TOOLS BY SIGMA', 'Equipamentos', '180', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSB7E9T60F82SP6QoNI1EwTKittVcu3gCn40Z1vOW-r2A&s=10', 'O Snow Foam Gravity da By Sigma é um canhão de espuma ativa por gravidade de alta performance, desenvolvido para produzir espuma densa e estável sem compressor de ar. Com reservatório superior e fluxo controlado por gravidade, oferece expansão máxima e cobertura uniforme de espuma em toda a carroceria. Compatível com a maioria das lavadoras de alta pressão.', NULL, '2026-07-22 11:31:11.093007+00', '800', '{"length":25,"width":15,"height":15,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('d6e91b7b-87e6-447a-a6f7-693bb2029791', 'Flash 500ml', 'Auto América', 'Pneus e rodas', '33.5', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRt0fXqZmxYRUJhOozIAiJTLzw1ztkiqljxijneHVXUqJA246uw0NZBtA&s=10', 'O Flash 500ml da Auto América é um revitalizador de pneus de ação rápida, formulado para proporcionar brilho profissional em segundos. Sua fórmula de fácil aplicação é indicada para uso em rotinas de lavagem rápida, devolvendo o aspecto de novo aos pneus sem necessidade de aguardar tempo de cura. Resultado imediato e visual impactante.', NULL, '2026-07-19 12:17:20.841073+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('03911292-d586-433f-863a-d184d75e29d6', 'filtro mesh', 'Nação Detail', 'Itens de reposição', '29', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQJic7qtHfOyeKMOBlFURXxNb-LyVocuzyykqP_MXr8iQ&s=10', 'O Filtro Mesh da Nação Detail é um filtro de malha fina desenvolvido para canhões e sistemas de espuma ativa, com a função de reter impurezas e partículas da água e do produto antes que entrem no bocal. Garante espuma mais limpa, consistente e sem entupimentos, prolongando a vida útil do equipamento. Encaixe padrão compatível com a maioria dos snow foams profissionais.', NULL, '2026-07-19 12:17:21.430765+00', '60', '{"length":10,"width":10,"height":5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('cf981d63-108f-43f7-9909-ea161f429c68', 'Médium cut foam pad yellow', 'Menzerna', 'Polimento', '110', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR5QnBKzIhbnvqckSkvVg6B7ya0Jk8Gao1-n5vQRsqkeA&s=10', 'O Médium Cut Foam Pad Yellow da Menzerna é um pad de polimento de corte médio, desenvolvido para a correção de riscos leves a moderados, swirls e oxidação superficial. Fabricado com espuma de alta qualidade, proporciona distribuição uniforme dos compostos de polimento e resultado consistente em toda a área trabalhada. Compatível com politrizes orbitais e rotativas.', NULL, '2026-07-19 12:17:20.841073+00', '120', '{"length":16,"width":16,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('08df4b90-e2da-4727-96a0-6e56fff13454', 'Prewash 500ml', 'Auto América', 'Lava auto', '18.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQYmJcFWVqq6bgyT9GAg_IUycyh4wzO6iQAEqJOPR9lgw&s=10', 'O Prewash 500ml da Auto América é um pré-lavagem alcalino prático e eficiente para uso no dia a dia da estética automotiva. Aplicado antes do shampoo, dissolve sujeiras pesadas e facilita a remoção de insetos, piche e graxa, tornando a lavagem principal mais rápida e segura para a pintura.', NULL, '2026-07-19 12:17:20.998748+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1ed7c639-5349-4721-b987-a8a63855fb77', 'Refil aplicador magic hand', 'Kers', 'Aplicadores', '19', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSfJP4sgT8SUXCZ-b-tictLI40ldqfmgFfDA37KbRvwRg&s=10', 'O Refil Aplicador Magic Hand da Kers é o refil de espuma de alta qualidade para o aplicador Magic Hand, permitindo renovar o componente de contato com a pintura a um custo muito menor que a troca do aplicador completo. Compatível com todos os modelos do aplicador Magic Hand, mantendo o alto padrão de aplicação e distribuição de ceras e selantes.', NULL, '2026-07-19 12:17:20.998748+00', '60', '{"length":16,"width":12,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
