INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('7c6051e5-308b-4b88-a638-2834c3d7c39c', 'Vexus 1,5L', 'Vonixx', 'Limpadores', '37.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTuLZ28QBwtvUddG_fQO0t51b65uNkJL4qtC4eZW5SWfA&s=10', 'O Vexus 1,5L da Vonixx é um limpador multiusos de alta eficiência em formato econômico, desenvolvido para a remoção de sujeiras moderadas a intensas em interiores e exteriores automotivos. Fórmula versátil e segura para uso em plásticos, borrachas, tecidos e superfícies pintadas. Alto rendimento e excelente custo-benefício para uso profissional.', NULL, '2026-07-22 11:31:11.093007+00', '1661', '{"length":9.65,"width":9.6,"height":30.5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('df54ff5e-e5fa-41a9-8086-d64818d9c459', 'v-eco fast 500ML', 'Vonixx', 'Limpadores', '25.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSDEjrXNwWP1zQueH-LaWk6rrrc7QWI7a3XPnR3FsfYEw&s=10', 'O V-Eco Fast da Vonixx é um limpador ecológico de alta eficiência para a limpeza interna do veículo, desenvolvido com fórmula biodegradável que respeita o meio ambiente sem comprometer a performance. Remove sujeiras, gordura e poeira de plásticos, painéis e tecidos com praticidade e rapidez. Seguro, eficaz e sustentável.', NULL, '2026-07-21 10:59:42.393339+00', '575', '{"length":6.6667,"width":6.5,"height":25}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0fdcb160-4009-45fe-a4e1-48385f783fdd', 'Snow foam manual detailer', 'Detailer', 'Equipamentos', '80', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSOLpry_pxa31KK2zfekBKA8bQv9x9qRDflmsMCxHnrzw&s=10', 'O Snow Foam Manual Detailer é um canhão de espuma ativa para lavadoras de alta pressão, desenvolvido para profissionais que buscam alto padrão na pré-lavagem sem contato. Produz espuma densa e uniforme que adere à carroceria, encapsulando sujeira e facilitando sua remoção com o enxágue. Construção robusta para uso profissional intensivo.', NULL, '2026-07-19 12:17:20.998748+00', '650', '{"length":25,"width":12,"height":12,"diameter":0}', 'Inativo') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('8febc065-991c-491e-a5e6-0ca907f16722', 'Heavy cut foam pad red', 'Menzerna', 'Polimento', '110', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTNj9NhUzMcsNusVOlJSVk8KAtTxmasSw0wcCBV6cTwhQ&s=10', 'O Heavy Cut Foam Pad Red da Menzerna é um pad de polimento de corte intenso, desenvolvido para remover riscos profundos, marcas de polimento pesado e defeitos severos de pintura. Fabricado com espuma de célula aberta de alta densidade, trabalha em conjunto com compostos abrasivos Menzerna para proporcionar eficiência máxima na correção de pintura. Compatível com politrizes orbitais e rotativas.', NULL, '2026-07-19 12:17:20.841073+00', '130', '{"length":16,"width":16,"height":4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('986257ef-022a-4ebb-a3c5-d4321ea327ab', 'Clean cap (diluição máxima 1/20) - ácido 5L', 'Magil Clean', 'Desengraxantes e desincrustantes', '64.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/pree1vvo5nf1788792210486.webp', 'O Clean-Cap da linha Snow Clean MagiClean é um poderoso desincrustante ácido, desenvolvido especialmente para a limpeza profunda de superfícies metálicas, como tanques e tubulações de inox ou alumínio em ambientes industriais. Sua fórmula altamente eficaz remove incrustações, resíduos minerais e oxidações, garantindo uma manutenção segura e eficiente dos equipamentos.', NULL, '2026-09-07 14:43:31.407754+00', '5300', '{"length":13,"width":19,"height":29,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
