INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('b644aef1-3a6a-40e3-bf85-cc47ee7fa159', 'Meta luster 473ml', 'Soft 99', 'Polimento', '82.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRhyWt8wnTVMKj7NUgthx2C6v1hwGJHqPFSW-JUcXvcHQ&s=10', 'O Meta Luster 473ml da Soft 99 é um polidor e lustrador de pintura metálica de tecnologia japonesa, desenvolvido para revelar e intensificar o brilho das pinturas metálicas e perolizadas. Sua fórmula exclusiva elimina micro-riscos e swirls enquanto deposita uma fina camada protetora com efeito espelhado. Resultado de concurso sem uso de politriz, apenas aplicação manual.', NULL, '2026-07-19 12:17:20.841073+00', '540', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1660a102-3cb6-4e62-969a-1126b858cb85', 'New Ar - Vita Lux 500ml', 'Alcance', 'Aromatizantes', '40', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR2eVg8eLpdremhzIFqKD2W3QaFiKyIEVZYNV1XM3tE1Q&s=10', 'O New Ar Vita Lux 500ml da Alcance é um aromatizante líquido concentrado para ambientes automotivos, com fragrância elegante e duradoura. Sua fórmula de alta concentração proporciona perfumação intensa e persistente, transformando o interior do veículo em um espaço mais agradável e refinado. Grande volume com excelente custo-benefício para uso diário.', NULL, '2026-07-21 10:59:42.780268+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('42fd0dd7-f879-4ebb-a77e-819841542ddf', 'ESCOVA DE MICROFIBRA PARA FUROS DE RODAS', 'KERS', 'Escovas e pincéis', '69.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/7l9annhpcl1788790390298.webp', 'Essas Escovas de Microfibra Kers são ideais para limpeza dos pequenos detalhes da roda, proporcionando uma limpeza perfeita do local. Com seu formato especial proporciona facilidade e agilidade na limpeza de locais de difícil acesso, possuindo um tecido que não danifica ou risca rodas cromadas ou pintadas. Limpa profundamente sem danificar. Além de serem compactas, facilitando a limpeza de áreas internas da roda e das áreas de pouca visibilidade.', NULL, '2026-09-07 14:13:11.26213+00', '150', '{"length":52,"width":9,"height":5,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('64287625-55a4-4bb7-91dc-279625c67791', 'Triple wax 500ml', 'Auto América', 'Ceras', '49.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS0JZHsdGw_e71yIHrTLeVAnYniff_7uYcyNEiUuZ-DLg&s', 'O Triple Wax 500ml da Auto América é uma cera de carnaúba tripla concentração em formato spray, desenvolvida para proporcionar brilho intenso e proteção avançada à pintura. Com três camadas de carnaúba em sua fórmula, cria uma proteção mais espessa e durável, intensificando o brilho e a profundidade da pintura. Aplicação rápida com resultado de acabamento profissional.', NULL, '2026-07-21 10:59:42.393339+00', '580', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
