INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('3e39ad86-a312-45cb-b9b8-fd683ea525e5', 'SMF - Limpador de microfibra antiestático 1l', 'Alcance', 'Específicos', '40', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRX-Q_psJfYdHKQOaxHoI7nU8x57drF9IHAdJL22Gpa3A&s', 'O SMF Limpador de Microfibra Antiestático da Alcance é um limpador específico para toalhas, luvas e pads de microfibra, desenvolvido para restaurar as propriedades originais das fibras e remover resíduos de compostos, ceras e produtos de detalhamento. Sua fórmula antiestática evita a atração de partículas de poeira após a lavagem, mantendo os acessórios limpos por mais tempo.', NULL, '2026-07-21 10:59:42.780268+00', '1100', '{"length":9,"width":9,"height":24}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('9b08c831-8cfb-410c-bd10-b1ab7fa68f8f', 'Garrafa translucida bocal 28mm', 'Nação Detail', 'Itens de reposição', '49.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEZwSy_dfnJqxNiC-vtLObqMAUDxtNfe1ddETJbNQySQ&s=10', 'A Garrafa Translúcida com Bocal 28mm da Nação Detail é um recipiente profissional desenvolvido para o armazenamento e diluição de produtos de detalhamento automotivo. Fabricada em material resistente e translúcido, permite a visualização do nível do produto com facilidade. O bocal de 28mm facilita o enchimento a partir de galões e embalagens grandes. Resistente a produtos químicos ácidos e alcalinos.', NULL, '2026-07-22 11:31:11.093007+00', '120', '{"length":8,"width":8,"height":25}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('e1b2696a-31a2-4110-b00b-14ed76b99b73', 'HOF 500g', 'Lincoln', 'Polimento', '145', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTkTqTJ5y9hYr58jrLgKZ65ItHSFUcPWjI_YvkV9WUIrQ&s=10', 'O HOF da Lincoln é um compound de polimento premium de corte agressivo, desenvolvido para a correção profissional de pinturas com danos severos, oxidação intensa e riscos profundos. Sua fórmula de alta performance elimina imperfeições rapidamente, preparando a superfície para o processo de lustro e acabamento. Um dos favoritos dos detailers profissionais brasileiros.', NULL, '2026-07-21 10:59:42.393339+00', '600', '{"length":8,"width":8,"height":10,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('2187439a-c818-423e-8689-b0c84df9a8c6', 'PNEU PRETINHO 5L SEMIGEL', 'Magil Clean', 'Pneus e rodas', '89.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/zs7fok633h1788792340817.webp', 'O Pneu Pretinho Semi-Gel da linha Snow Clean MagiClean é a solução ideal para quem deseja realçar o visual dos pneus, proporcionando um acabamento brilhante, durável e uniforme. Sua fórmula de alta resistência protege contra o ressecamento, garantindo maior longevidade e aspecto renovado para os pneus do seu veículo.\n\nCom textura semigel, o produto oferece fácil aplicação e melhor aderência, evitando respingos e proporcionando uma secagem rápida e eficaz. Além do brilho intenso, ajuda a manter os pneus com aparência de novos por mais tempo.', NULL, '2026-09-07 14:45:41.871567+00', '5800', '{"length":13,"width":19,"height":28,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('cb7f18ff-5484-4f93-9465-f59656b55fff', 'Snake leather 500ml', 'Jaça', 'Couro', '39.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcReC15E8wgEsnDqe37W3l4WjhsVzp4dihk9_lWAKuS1Ig&s=10', 'O Snake Leather 500ml da Jaça é um hidratante e condicionador de couro de alto desempenho, desenvolvido para nutrir, suavizar e proteger bancos, volante e demais superfícies de couro genuíno e sintético. Sua fórmula com ativos penetrantes alimenta o couro de dentro para fora, prevenindo rachaduras e ressecamento causados pelo tempo e pelos raios UV.', NULL, '2026-07-19 12:17:20.998748+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('86cae1b3-d96b-486a-97c2-027f96eb46dd', 'Snow foam manual ediçao hexa', 'SGT TOOLS BY SIGMA', 'Equipamentos', '60', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTc9Q4WlyF0nvev0ZT8_XqHnSbkgWzYowU5Ao9tE_h2MA&s=10', 'O Snow Foam Manual Edição Hexa da By Sigma é um canhão de espuma ativa com design exclusivo e ergonômico inspirado no formato hexagonal, desenvolvido para proporcionar alta produção de espuma com máxima facilidade de uso. Compatible com lavadoras de alta pressão, entrega cobertura uniforme e espuma de alta expansão. Uma peça que chama atenção no setup de qualquer detailer.', NULL, '2026-07-19 12:17:20.998748+00', '700', '{"length":25,"width":12,"height":12,"diameter":0}', 'Inativo') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('edb872d0-f509-4959-b516-34a3f915562d', 'Neon 500ml', 'Auto América', 'Lava auto', '24.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRBkM1wA91rYuXHzKgZWx2ol2MWwz_GVz2pku9gNZhihQ&s=10', 'O Neon 500ml da Auto América é um shampoo automotivo de alta eficiência com fragrância marcante, formulado para a lavagem completa do veículo. Sua fórmula com agentes de limpeza avançados remove eficientemente sujeira, barro e resíduos orgânicos, gerando espuma abundante que facilita o deslizamento da esponja ou luva de lavagem. Não agride ceras ou selantes existentes.', NULL, '2026-07-19 12:17:20.841073+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('798d7348-a8a4-4ab6-aabb-2685c6e5195c', 'Nuber 240ml', 'Razux', 'Motocicletas', '29.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRKZbPJwy8IOLKwMCBW9YUVSXzbtm8R6r2ujoHx-9mWTw&s=10', 'O Nuber 240ml da Razux é um produto desenvolvido exclusivamente para o detalhamento e proteção de motocicletas, atuando na limpeza e renovação de plásticos, cromados e pinturas. Sua fórmula especializada para o universo das motos entrega proteção eficiente contra intempéries, mantendo o visual da motocicleta sempre impecável.', NULL, '2026-07-19 12:17:20.841073+00', '297', '{"length":5.33,"width":5,"height":20}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('995e5af1-5813-4d9a-85a2-5222a11e49db', 'Remogan 500ml', 'Jaça', 'Específicos', '57.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQWW9HjeLfzeLl5cjaoPY7E8yeOcE0xxezOXCQakBSlyQ&s=10', 'O Remogan da Jaça é um removedor de manchas e incrustações especializadas de alta eficácia, desenvolvido para eliminar resíduos difíceis como chuva ácida, manchas de calcário, cimento e água mineral das superfícies automotivas. Sua fórmula de ação química penetrante dissolve os depósitos minerais sem agressão à pintura quando utilizado corretamente.', NULL, '2026-07-21 10:59:42.780268+00', '570', '{"length":7,"width":7,"height":21,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('a48712f3-f515-4272-a7df-7458733d3199', 'pistola de pulverização', 'Vonixx', 'Equipamentos', '139.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRSw7EAPrzV6ZXxE_WPjt41pV5JFmp3aR0BiCMWUZLBJA&s=10', 'A Pistola de Pulverização da Vonixx é um equipamento de aplicação profissional para produtos líquidos de detalhamento automotivo. Com sistema de atomização de alta eficiência, distribui o produto de forma uniforme e controlada em toda a superfície, reduzindo desperdício e proporcionando aplicação mais rápida e homogênea. Compatível com a maioria dos produtos de detalhamento.', NULL, '2026-07-19 12:39:30.271359+00', '423', '{"length":8.3,"width":10,"height":17.4}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6ca8e2a1-b610-442c-9277-f195e9ae4405', 'Revelax 500ml', 'Vonixx', 'Específicos', '32.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQR7SyNo_K_TzEPpFwTtQAgw4hp8LTEpnr_2RG035Z_JA&s=10', 'O Revelax 500ml da Vonixx é um limpador revelador de incrustações ferrosas e contaminação da pintura, desenvolvido para identificar e remover partículas metálicas invisíveis a olho nu. Ao ser aplicado, reage com os contaminantes ferrosos mudando de cor, indicando visualmente as áreas afetadas. Essencial no processo de descontaminação química antes do polimento.', NULL, '2026-07-19 12:17:20.998748+00', '546', '{"length":6.66667,"width":6.5,"height":25}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('1916f150-ff9e-4ab1-8b4c-64484cb0c3f5', 'pulviflex 5l', 'Vintex', 'Específicos', '82.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSOZcNvqi-zulCqtYlZYSfECYr3-tVnxJthRZ44cFEE7Q&s', 'O Pulviflex da Vintex é um protetora e renovador em spray para plásticos e superfícies de borracha, desenvolvido para uso interno e externo. Sua fórmula penetrante revitaliza e protege plásticos desbotados, painéis, molduras e borrachas, devolvendo a cor original e criando uma barreira protetora contra UV e intempéries. Acabamento fosco que transmite sofisticação.', NULL, '2026-07-21 10:59:42.393339+00', '5100', '{"length":16,"width":17.5,"height":31.5}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('4a72d7ce-e0d1-42bf-a38f-ffe788793b71', 'Protectant 473ML', 'Mothers', 'Plásticos', '119.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRSw6YsxbGu1wTLKB08p3H3bSisxqaju7uI1qSGgSbAVg&s=10', 'O Protectant 473ml da Mothers é um condicionador e protetor americano de referência para plásticos, vinílicos, borrachas e superfícies internas e externas do veículo. Sua fórmula exclusiva revitaliza, nutre e protege os materiais contra o ressecamento e a ação dos raios UV, devolvendo o aspecto de novo com acabamento acetinado. Um dos best-sellers da marca Mothers no mundo.', NULL, '2026-07-19 12:17:20.998748+00', '540', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('80604a4e-085d-4dd7-b706-005f8f6f2657', 'HFF 500g', 'Lincoln', 'Polimento', '140', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS2B8kT4O0xDe_j4pULxfRqnWM05ZC70jvDVlKaoOoalw&s=10', 'O HFF 500g da Lincoln é um composto de polimento de corte médio-alto, desenvolvido para a correção de oxidação, riscos e swirls em pinturas moderadamente comprometidas. Sua fórmula de granulometria controlada permite trabalho eficiente sem gerar excesso de calor na pintura. Compatível com politrizes orbitais e rotativas, proporciona acabamento uniforme antes do lustro final.', NULL, '2026-07-19 12:39:30.271359+00', '600', '{"length":8,"width":8,"height":10,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6a3469a9-85da-4844-b4a3-599b14293356', 'oxy force 500ml', 'Auto América', 'Limpadores', '25.5', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRSlBZnkESmmWBr2KIPz6a1-AUXOpyW-KhLM5rcel6vGQ&s', 'O Oxy Force da Auto América é um limpador multiusos de alta performance com tecnologia oxidante, desenvolvido para a remoção de manchas orgânicas, bactérias e odores indesejados em estofados, tapetes e superfícies internas. Sua ação profunda elimina contaminações difíceis como sangue, café, urina e gordura animal, deixando o interior higienizado e sem odor.', NULL, '2026-07-21 10:59:42.393339+00', '570', '{"length":7,"width":7,"height":21}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('e5143858-703b-46d2-b625-a0a5dbdc1e88', 'Suporte 5'' ROSCA 5/8 VELCRADO', 'SGT TOOLS BY SIGMA', 'Polimento', '56.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT_8pBh9lYmOzyNat_vEXn61KJcwi_1WtuB2QOhDNzE7A&s=10', 'O Suporte 5" Rosca 5/8 Velcrado da By Sigma é um backing plate de alta qualidade para politrizes com rosca 5/8, desenvolvido para suportar boinas de 5 polegadas com sistema de fixação por velcro. Fabricado com material resistente e balanceado, minimiza vibrações durante o polimento e garante distribuição uniforme de pressão em toda a boina.', NULL, '2026-07-19 12:17:20.998748+00', '300', '{"length":20,"width":10,"height":10,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6c5a861f-434e-4128-89c6-ea98fa2176c1', 'BALDE 18L TRANSPARENTE COM SEPARADOR DE PARTICULAS', 'SGT TOOLS BY SIGMA', 'Acessórios', '90', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/1e542ee1ed41788793069337.webp', 'É o acessório ideal para uma lavagem perfeita e segura em seu veículo.\n\nA função principal, é impedir que as impurezas que vão se acumulando no fundo do balde de lavagem subam e entre em contato com a luva ou esponja, reduzindo assim a possibilidade de riscos.\n\nAs impurezas ficam depositadas no fundo do balde, apara que tanto a água como o produto de limpeza permaneçam sempre limpos. A solução fácil para uma lavagem livre de arranhões.', NULL, '2026-09-07 14:57:50.295586+00', '855', '{"length":30,"width":30,"height":34,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('7120ae4a-a51e-4a09-a301-c3481f4f39f2', 'Toalha de secagem premium cinza 60x90cm 600gsm', 'Lincoln', 'Toalhas', '49.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSvkgERYv9wwyreWVgxWO1gG1cIc04gJLTbVxkupuZR7w&s=10', 'A Toalha de Secagem Premium Cinza 60x90cm 600gsm da Lincoln é uma toalha de secagem profissional de grandes dimensões e altíssima gramatura, desenvolvida para a secagem rápida e segura de veículos de qualquer tamanho. A gramatura 600gsm garante absorção máxima e a textura suave evita marcas ou arranhões na pintura. Dimensões generosas para secagem eficiente.', NULL, '2026-07-21 10:59:42.780268+00', '220', '{"length":92,"width":62,"height":2}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('bf744d80-b6b9-4e84-93ff-100a58a6bcce', 'ESPONJA MAGICA DE MELAMINA 2UNID', 'KERS', 'Descontaminante', '18.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/7uurxjx7isp1788790843458.webp', 'A Solução Eficiente para Limpeza Automotiva. A esponja multiuso é cuidadosamente confeccionada para atender às exigências da limpeza automotiva, oferecendo um desempenho excepcional na remoção de sujeiras e impurezas em diversos materiais, como couro, vinil, borracha e plásticos.', NULL, '2026-09-07 14:20:44.583335+00', '16', '{"length":20,"width":16,"height":3,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('0f9699c7-6e61-46d4-b378-155bd74a8b99', 'Ultra limpador 1,15L', 'Magil Clean', 'Limpadores', '54.89', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRnsR0dk07Kkpkgj9UvgwP4Z5Yk2B9XwdBDZ6tm51SZQ&s=10', 'O Ultra Limpador 1,15L da Magil Clean é um limpador multiusos de alta concentração e máxima performance, desenvolvido para a remoção de sujeiras extremas em ambientes automotivos e industriais. Sua fórmula poderosa age sobre gorduras, óleos, graxas e sujeiras orgânicas com eficiência incomparável, sendo indicado para uso em pisos de garagem, motores e áreas externas.', NULL, '2026-07-21 10:59:42.393339+00', '1300', '{"length":10,"width":10,"height":28,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('6af2c6c7-11e5-437c-8097-6a3f5f9fc401', 'silvermax 1,5l', 'Auto América', 'Desengraxantes e desincrustantes', '28.9', 'https://gieubdiyzjphtkvwaawp.supabase.co/storage/v1/object/public/produtos/produtos/ca5mhrdai8a1789065584299.webp', 'O Silver Max da Autoamerica foi desenvolvido especialmente para limpeza de rodas, removendo com facilidade sujeiras pesadas como pó de freio, fuligem e resíduos acumulados', NULL, '2026-09-10 18:39:45.847868+00', '1500', '{"length":9,"width":9,"height":25,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('bf8aa51c-cdc5-45ee-a957-b3f082f64b92', 'Super Clean cap (diluição máxima 1/100) - ácido 5L', 'Magil Clean', 'Desengraxantes e desincrustantes', '169.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRfj8hRDswXmFIqNN_JShR6iq1HRnqA8K5CaBtE57kgiw&s', 'O Super Clean CAP Ácido 5L da Magil Clean é um descontaminante ácido de altíssima concentração com diluição máxima de 1:100, desenvolvido para a remoção de incrustações minerais pesadas, ferrugem, cimento, cal e depósitos calcários em rodas, carrocerias e superfícies industriais. Alta performance para os casos de contaminação mais severos.', NULL, '2026-07-22 11:31:11.093007+00', '6250', '{"length":18,"width":18,"height":31,"diameter":0}', 'Fora de estoque') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.products (id, name, brand, category, price, img_url, description, badge_text, created_at, weight, dimensions, status) VALUES ('12e9d9a7-9231-4a00-b3f7-f5e3fdb210f9', 'KIT 3 BOINAS HYPER AMERICAN FOAM 5"', 'Kers', 'Polimento', '154.9', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRPz40ZzAt8ssL5qqiDTpFJQq7A9f7H6utcI4SW2hiA0g&s=10', 'O Kit Hyper 5" da Kers foi desenvolvido para quem busca alto desempenho em todas as etapas do polimento automotivo. Com tecnologia Hexagonal, essas boinas garantem melhor distribuição do produto, fluxo de ar otimizado e redução de superaquecimento, proporcionando resultados precisos e acabamento profissional.\n\n— Corte eficaz em imperfeições mais profundas da pintura.\n— Refino perfeito, eliminando micro-riscos e marcas de redemoinho.\n— Lustro final de alto brilho, deixando a pintura impecável.\n— Maior controle e segurança durante o polimento graças ao design hexagonal.\n— Melhora a eficiência do polimento e proporciona controle seguro.\n\n\nVerde Agressiva – Corte pesado\nLaranja Média – Refino\nAzul Suave – Lustro e acabamento final\n\n\nConteúdo do Kit:\n1 Boina Hyper Verde Agressiva 5"\n1 Boina Hyper Laranja Média 5"\n1 Boina Hyper Azul Suave 5"', NULL, '2026-07-21 10:59:42.393339+00', '450', '{"length":20,"width":20,"height":10,"diameter":0}', 'Disponível') ON CONFLICT (id) DO NOTHING;
