-- 1. TABELA PRODUCTS (Produtos, Pesos, Dimensões, Fotos e Preços)
CREATE TABLE IF NOT EXISTS public.products (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    brand TEXT,
    category TEXT,
    price NUMERIC,
    img_url TEXT,
    description TEXT,
    badge_text TEXT,
    badge_style TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    weight NUMERIC,
    dimensions TEXT,
    status TEXT DEFAULT 'Disponível'
);
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read products" ON public.products FOR SELECT USING (true);
CREATE POLICY "Service role all products" ON public.products FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 2. TABELA ORDERS (Pedidos)
CREATE TABLE IF NOT EXISTS public.orders (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    customer_name TEXT,
    customer_email TEXT,
    customer_phone TEXT,
    customer_cep TEXT,
    customer_address TEXT,
    customer_number TEXT,
    customer_complement TEXT,
    customer_district TEXT,
    customer_city TEXT,
    customer_state TEXT,
    items JSONB,
    total NUMERIC,
    status TEXT DEFAULT 'pending',
    payment_method TEXT,
    installments INTEGER DEFAULT 1,
    pix_discount NUMERIC,
    coupon_code TEXT,
    coupon_discount NUMERIC,
    user_id UUID,
    created_at TIMESTAMPTZ DEFAULT now()
);
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public insert orders" ON public.orders FOR INSERT WITH CHECK (true);
CREATE POLICY "Service role all orders" ON public.orders FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 3. TABELA RAFFLE_TICKETS (Sorteio Mensal)
CREATE TABLE IF NOT EXISTS public.raffle_tickets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    order_id UUID,
    ticket_number INTEGER NOT NULL UNIQUE,
    customer_name TEXT,
    customer_email TEXT,
    customer_phone TEXT,
    order_total NUMERIC,
    raffle_month TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_raffle_month ON public.raffle_tickets(raffle_month);
CREATE INDEX IF NOT EXISTS idx_raffle_ticket_number ON public.raffle_tickets(ticket_number);
ALTER TABLE public.raffle_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role all raffle" ON public.raffle_tickets FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 4. TABELA SITE_SETTINGS (Configurações da Loja)
CREATE TABLE IF NOT EXISTS public.site_settings (
    id TEXT PRIMARY KEY,
    value TEXT
);
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read site_settings" ON public.site_settings FOR SELECT USING (true);
CREATE POLICY "Service role all site_settings" ON public.site_settings FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 5. TABELA TESTIMONIALS (Depoimentos)
CREATE TABLE IF NOT EXISTS public.testimonials (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ DEFAULT now(),
    name TEXT,
    role TEXT,
    content TEXT,
    rating INTEGER DEFAULT 5
);
ALTER TABLE public.testimonials ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public read testimonials" ON public.testimonials FOR SELECT USING (true);
CREATE POLICY "Service role all testimonials" ON public.testimonials FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 6. TABELA PROFILES
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID PRIMARY KEY,
    email TEXT,
    full_name TEXT,
    phone TEXT,
    address TEXT,
    created_at TIMESTAMPTZ DEFAULT now()
);
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Service role all profiles" ON public.profiles FOR ALL TO service_role USING (true) WITH CHECK (true);

-- 7. TABELA WAITLIST
CREATE TABLE IF NOT EXISTS public.waitlist (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id UUID,
    email TEXT,
    created_at TIMESTAMPTZ DEFAULT now(),
    notified BOOLEAN DEFAULT false
);
ALTER TABLE public.waitlist ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public insert waitlist" ON public.waitlist FOR INSERT WITH CHECK (true);
CREATE POLICY "Service role all waitlist" ON public.waitlist FOR ALL TO service_role USING (true) WITH CHECK (true);

